'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='précis'?'Etymonline: https://www.etymonline.com/word/precis':w==='precocial'?'Etymonline: https://www.etymonline.com/word/precocious':w==='preeminent'?'Etymonline: https://www.etymonline.com/word/pre-eminent':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('precinct','Precinct comes from Medieval Latin precinctum, “enclosure or boundary,” from praecingere, “to gird around,” with prae- “before” and cingere “surround.”',C('precinct.s1','辖区；区域','The election team placed signs at every entrance to the precinct assigned to the east-side polling station.','选举工作人员在东区投票站所属辖区的每个入口都放置了指示牌。','The election team placed signs / at every entrance to the precinct / assigned to the east-side polling station.','precinct 指为某种用途划定的区域或辖区。','这个区域有明确边界，并服务于特定投票站。'),M('The election team called the whole country one precinct even though the polling district covered only three city blocks.','The team marked the three-block polling district as a precinct.','一个仅覆盖三条街区的选区不能指整个国家。','meaning'),[q('Where did the team place signs?','at entrances to the polling precinct','inside a chemical laboratory vessel','along a steep mountain cliff','标牌放在投票辖区入口。'),q('What is a precinct?','a defined area assigned to a particular use','a boundary-free collection of unrelated cities','a short summary of a speech','precinct 是划定用途的区域。',1,'meaning'),q('Which could be a precinct?','a city district assigned to one polling station','a single voter’s private promise','a rainfall measurement','专属某投票站的城市区块可称为 precinct。',1,'context'),q('Which Latin verb is related to precinct through precinctum?','praecingere, “to surround”','praecidere, “to cut short”','praedari, “to plunder”','precinctum 源自 praecingere，意为围绕。',1,'word-formation')]);
P('precious','Precious came through Old French precios from Latin pretiosus, “costly or valuable,” from pretium “price or worth”; it can describe something rare, dearly loved, or affectedly delicate.',[C('precious.s1','珍贵的；贵重的','The archive kept the precious first edition in a locked case because only a few copies survived.','档案馆把这本珍贵的初版书锁在展柜中，因为存世的副本很少。','The archive kept the precious first edition / in a locked case / because only a few copies survived.','precious.s1 指因稀少或价值高而贵重的物品。','存世副本稀少，支持“珍贵”这一含义。'),C('precious.s2','心爱的；珍视的','After the evacuation, the child clutched a precious family photograph that her grandmother had carried for decades.','撤离后，孩子紧紧抱着一张珍爱的家庭照片，祖母已珍藏数十年。','The child clutched a precious family photograph / that her grandmother / had carried for decades.','precious.s2 强调被人珍爱、视为重要的事物。','照片承载家庭记忆，家人长久珍藏。'),C('precious.s3','做作的；矫揉造作的','The actor’s precious delivery made every ordinary sentence sound unnaturally delicate and self-conscious.','演员矫揉造作的表达方式让每句普通话都显得刻意娇柔、过分讲究。','The actor’s precious delivery / made every ordinary sentence sound / unnaturally delicate and self-conscious.','precious.s3 是贬义，指举止或表达过分精致、不自然。','普通句子被刻意说得娇柔做作。')],M('The actor gave a precious performance by speaking naturally and plainly, without any affected delicacy.','The actor gave a precious performance by making ordinary lines sound affectedly delicate.','自然直白的表达与做作矫饰的语气相反。','meaning'),[q('Why was the first edition precious to the archive?','few copies of it survived','it was a freely distributed modern reprint','the pages were deliberately left blank','存世副本少，因此版本稀有贵重。',1,'context'),q('Why was the family photograph precious to the child?','it was dearly loved and carried by her grandmother for years','it was expensive because it was a rare book','it made every sentence sound affected','照片是家人珍视的纪念物。',2,'context'),q('What does precious mean in the actor review?','unnaturally delicate and affected in manner','rare and costly','beloved and emotionally important','这里批评演员的表达矫揉造作。',3,'meaning'),q('Which Latin noun is the source of precious?','pretium, “price or worth”','prae, “before”','praeda, “prey”','precious 最终来自表示价值、价格的拉丁词 pretium。',1,'word-formation')]);
P('precipice','Precipice came from French and Latin praecipitium, “a steep place or headlong fall,” related to prae “before” and caput “head.”',C('precipice.s1','悬崖','The rescue crew anchored two ropes before lowering a medic down the precipice to the stranded climber.','救援队先固定好两根绳索，才把医护人员沿悬崖放下去救助受困的登山者。','The crew anchored two ropes / before lowering a medic / down the precipice.','precipice 指非常陡峭的悬崖或峭壁。','救援人员必须沿陡壁下降才能到达登山者。'),M('The hikers called the level meadow a precipice and safely walked across its completely flat surface.','The hikers called the sheer rock face a precipice and stayed well back from its edge.','平坦草地不是陡峭悬崖。','meaning'),[q('How did the medic reach the stranded climber?','the crew lowered the medic down the steep precipice','the medic walked across a flat meadow','the climber voted in a public plebiscite','救援人员把医护人员沿悬崖放下。'),q('What is a precipice?','a very steep cliff','a district assigned to a polling station','a summary of a speech','precipice 指陡峭悬崖。',1,'meaning'),q('Which landscape feature is a precipice?','a sheer rock face dropping sharply into a ravine','a gently sloping lawn beside a house','a shallow puddle after rain','陡直落入峡谷的岩壁是悬崖。',1,'context'),q('Which Latin word is part of the history of precipice?','praecipitium, “a steep place”','praecingere, “to surround”','precarium, “obtained by asking”','precipice 经法语来自拉丁语 praecipitium。',1,'word-formation')]);
P('precipitate','Precipitate ultimately comes from Latin praecipitare, “to throw headlong”; English uses it for causing an event, a solid separated from liquid, or an action done too hastily.',[C('precipitate.s1','促成；使突然发生','The unexpected resignation precipitated a cabinet reshuffle before the budget debate began.','意外辞职促使内阁在预算辩论开始前突然改组。','The resignation precipitated a cabinet reshuffle / before the budget debate / began.','precipitate.s1 作动词，表示促使某事突然发生。','辞职直接引发了内阁改组。'),C('precipitate.s2','沉淀物','When the two solutions were mixed, a pale precipitate formed at the bottom of the glass beaker.','两种溶液混合后，烧杯底部形成了淡色沉淀物。','A pale precipitate formed / at the bottom of the beaker / when the solutions were mixed.','precipitate.s2 作名词，指化学变化中从液体分离出的固体。','固体出现在溶液混合后的烧杯底部。'),C('precipitate.s3','仓促的；鲁莽的','The board rejected a precipitate decision to close the clinic before reviewing patient data and costs.','董事会拒绝在审查患者数据和成本前仓促关闭诊所的决定。','The board rejected a precipitate decision / to close the clinic / before reviewing the data.','precipitate.s3 作形容词表示行动过快、欠考虑。','董事会指出决定尚未经过必要审查。')],M('The board made a precipitate decision after months of careful review and several rounds of public consultation.','The board made a precipitate decision without reviewing the evidence or consulting patients.','经过数月审议和多轮咨询不属于仓促决定。','meaning'),[q('What did the resignation precipitate?','a cabinet reshuffle','a solid collecting at the bottom of a beaker','a measured survey of a garden plot','辞职促成了内阁改组。',1,'context'),q('What formed in the beaker?','a solid precipitate','a precious first edition','a steep cliff','溶液混合后形成固体沉淀。',2,'context'),q('Why was the closure proposal called precipitate?','it was made too quickly without reviewing evidence','it caused a chemical solid to form','it followed months of detailed study','决定未审查证据就作出，因此仓促。',3,'meaning'),q('Which Latin verb is the origin of precipitate?','praecipitare, “to throw headlong”','praecingere, “to surround”','praecurrere, “to run before”','precipitate 最终源自拉丁语 praecipitare。',1,'word-formation')]);
P('precipitation','Precipitation comes from Latin praecipitatio, originally “a falling headlong or haste”; it now commonly names atmospheric water and also retains haste and chemical senses.',[C('precipitation.s1','降水；降水量','The weather station measured heavy precipitation overnight, including rain that turned to snow above the ridge.','气象站测得夜间降水量很大，包括山脊上方由雨转成的雪。','The station measured heavy precipitation / overnight / including rain and snow.','precipitation.s1 指从大气落到地面的雨、雪、冰雹等水分。','雨和雪都属于大气降水。'),C('precipitation.s2','仓促；沉淀','The chemist noted the precipitation of a white solid after the reagent was added, while the manager warned against precipitation in approving the costly plan.','加入试剂后化学家观察到白色固体沉淀；与此同时，经理提醒不要仓促批准昂贵的计划。','The chemist noted precipitation of a solid / while the manager warned against precipitation / in approving the plan.','precipitation.s2 可指化学沉淀过程，也可指仓促行事。','同一义项包括固体析出和行动过急两种来源列明的用法。')],M('The forecast reported heavy precipitation, but the sky remained cloudless and not a drop of water fell.','The forecast reported heavy precipitation as rain and snow fell through the night.','无云且没有降水与“降水量大”矛盾。','meaning'),[q('What did the station measure overnight?','rain and snow falling from the atmosphere','a chemical promise made by the cabinet','the number of residents in a precinct','气象站测量夜间雨雪降水。'),q('What happened after the reagent was added?','a white solid separated from the solution','the solution became a steep precipice','the manager made a public pledge','试剂加入后出现白色固体沉淀。',2,'context'),q('What does precipitation mean in “avoid precipitation in approving the plan”?','haste or acting too quickly','rainfall or snowfall','a precious object','此处 precipitation 表示仓促行事。',2,'meaning'),q('Which Latin noun is precipitation derived from?','praecipitatio, “a falling headlong or haste”','praecinctum, “an enclosure”','praecursor, “a forerunner”','precipitation 源自拉丁语 praecipitatio。',1,'word-formation')]);
P('precipitous','Precipitous came through French from Vulgar Latin *praecipitosus, related to praecipitare “to throw headlong”; it describes a sheer slope or a sudden, rash action.',[C('precipitous.s1','陡峭的','A narrow trail crossed the precipitous ridge, so the guide asked hikers to keep to the marked path.','一条狭窄小径横穿陡峭山脊，因此向导要求徒步者沿标记路线行走。','A narrow trail crossed the precipitous ridge / so the guide asked hikers / to keep to the marked path.','precipitous.s1 形容地势陡直、近乎垂直。','山脊地形陡峭，行走需要遵守路线。'),C('precipitous.s2','急遽的；轻率的','The company’s precipitous expansion into five countries left its support teams understaffed within a few months.','公司贸然迅速扩张到五个国家，几个月内客服团队就人手不足。','The company’s precipitous expansion / left its support teams understaffed / within a few months.','precipitous.s2 可形容变化急剧，也可形容过于仓促的行动。','短时间扩张过快，导致后续资源跟不上。')],M('The trail was precipitous because it crossed a wide, level plain with no slope or drop.','The trail was precipitous where it followed a sheer ridge above the valley.','宽阔平坦的平原不是陡峭地形。','meaning'),[q('Why did the guide insist hikers stay on the marked path?','the trail crossed a steep ridge','the company had expanded too quickly','the archive stored a rare edition','陡峭山脊上的路线需要谨慎通行。',1,'context'),q('What happened after the company’s precipitous expansion?','support teams lacked enough staff','the company grew gradually over many years','a solid formed in a beaker','迅速扩张让客服团队很快缺人。',2,'context'),q('What does precipitous describe in the sentence about expansion?','a sudden or rashly rapid change','a sheer cliff face only','a concise written summary','这里指扩张急剧、仓促。',2,'meaning'),q('Which verb is linked to the history of precipitous?','praecipitare, “to throw headlong”','praecingere, “to encircle”','praedari, “to plunder”','precipitous 与拉丁语 praecipitare 的“头朝下投掷”有关。',1,'word-formation')]);
P('précis','Précis is a French noun from précis “cut short or condensed,” related to Latin praecisus, the past participle of praecidere “cut off.”',C('précis.s1','摘要；概要','The editor asked the reporter to submit a one-page précis of the lengthy interview before the morning meeting.','编辑要求记者在晨会前提交这篇长篇采访的一页摘要。','The editor asked for a one-page précis / of the lengthy interview / before the meeting.','précis 指对讲话或文章主要内容的简短概述。','一页内容概括长篇采访，符合摘要的定义。'),M('The reporter’s précis repeated the entire two-hour interview word for word and added several new chapters.','The reporter’s précis briefly summarized the interview’s main points.','逐字重复全文并增加章节不是简短摘要。','meaning'),[q('What did the editor request?','a one-page summary of the interview','the complete recording transcribed word for word','a district map for the polling station','编辑要的是一页采访摘要。'),q('What is a précis?','a short summary of a speech or writing','a very steep cliff','a solid that separates from a liquid','précis 指简短的内容概要。',1,'meaning'),q('Which document is a précis?','a concise outline of a long report’s main findings','a full copy of every page of the report','an unrelated list of election precincts','简洁概括报告要点的文件是摘要。',1,'context'),q('What does French précis literally suggest in its history?','cut short or condensed','surrounded by a boundary','hunted as prey','précis 与法语“缩短、压缩”有关。',1,'word-formation')]);
P('precise','Precise came from Old French précis and Latin praecisus, “cut off or abridged,” the past participle of praecidere “cut short”; it means exact or carefully exact.',[C('precise.s1','精确的；确切的','The surveyor recorded the precise distance from the marker to the bridge as 18.42 metres.','测量员把标记到桥梁的精确距离记录为18.42米。','The surveyor recorded the precise distance / from the marker to the bridge / as 18.42 metres.','precise.s1 表示细节正确、不是近似值。','准确到厘米的测量数值体现精确。'),C('precise.s2','严谨的；一丝不苟的','The precise archivist returned each map to its numbered sleeve and checked every label before closing the collection.','严谨的档案员把每张地图放回编号套袋，闭馆前逐一核对标签。','The precise archivist returned each map / to its numbered sleeve / and checked every label.','precise.s2 描写做事认真、特别注意细节的人。','档案员逐张归位并核验标签，体现一丝不苟。')],M('The surveyor gave a precise distance of “somewhere between ten and fifty metres” and refused to take an exact measurement.','The surveyor gave a precise distance of 18.42 metres after measuring the route.','宽泛范围且拒绝测量不是精确数值。','meaning'),[q('What distance did the surveyor record?','18.42 metres','somewhere between ten and fifty kilometres','the number of surviving book copies','测量记录给出了18.42米这一精确距离。',1,'context'),q('Why is the archivist called precise?','the archivist carefully checks every label and numbered sleeve','the archivist mixes maps together without checking them','the archivist writes a short speech summary','细致核对每张地图说明其严谨。',2,'context'),q('Which measurement is precise?','the sample weighed 6.315 grams','the sample was fairly heavy','the sample weighed somewhere from one to ten grams','给出细致、准确数值的测量是 precise。',1,'meaning'),q('Which Latin verb is related to precise through praecisus?','praecidere, “to cut off or shorten”','praecingere, “to surround”','praecurrere, “to run ahead”','precise 与拉丁语 praecidere“切短”有关。',1,'word-formation')]);
P('precisely','Precisely is precise + -ly; it means exactly or with exactness, and it can also affirm that a point is exactly right.',C('precisely.s1','精确地；恰好','The technician aligned the lens precisely with the center mark, then tightened the mount without shifting it.','技术员把镜头精确对准中心标记，然后拧紧支架，过程中没有让镜头偏移。','The technician aligned the lens precisely / with the center mark / then tightened the mount.','precisely 修饰 aligned，说明对准位置非常准确。','镜头与中心标记对齐且没有偏移。'),M('The technician aligned the lens precisely by placing it several centimetres away from the center mark.','The technician aligned the lens precisely with the center mark before tightening the mount.','远离中心标记不能算准确对准。','meaning'),[q('Where did the technician align the lens?','exactly with the center mark','several centimetres away from the mark','inside a different laboratory','镜头与中心标记精确对齐。'),q('What does precisely mean in this sentence?','in an exact way','in a hasty and careless way','in a manner that is overfull','precisely 表示精确地。',1,'meaning'),q('Which instruction uses precisely correctly?','Place the sensor precisely at the point marked in red.','Place the sensor precisely somewhere near the equipment.','Precisely the sensor placed the point.','precisely 修饰 at the point，说明位置精确。',1,'grammar'),q('Which adjective is precisely formed from?','precise','precious','precocial','precisely 由 precise 加 -ly 构成。',1,'word-formation')]);
P('precision','Precision is formed from precise + -ion and names the quality of being exact.',C('precision.s1','精确；精度','The machining team improved the precision of the gears so that each tooth fit its partner with almost no gap.','加工团队提高了齿轮的精度，使每个齿都能几乎无缝地与另一齿轮咬合。','The team improved the precision of the gears / so that each tooth fit / with almost no gap.','precision 指精确、准确的程度或品质。','齿轮齿形与咬合间隙被控制得更准确。'),M('The machine had high precision because its measurements changed unpredictably by several centimetres each time.','The machine had high precision because repeated measurements differed by only a fraction of a millimetre.','测量每次变化数厘米说明精度低。','meaning'),[q('What improved when the gears were machined more accurately?','their precision','their preciousness','their precipitousness','加工精度提高，齿轮能紧密咬合。'),q('What does precision mean?','the quality of being very exact','the act of hurrying without thought','the area surrounding a polling station','precision 指准确、精确的品质。',1,'meaning'),q('Which instrument shows high precision?','one that gives nearly identical readings in repeated tests','one whose readings vary widely each time','one that cannot detect the object at all','重复测量结果高度一致说明精度高。',1,'context'),q('Which adjective is the base of precision?','precise','precipitate','precinct','precision 由 precise 加名词后缀 -ion 构成。',1,'word-formation')]);
P('preclude','Preclude comes from Latin praecludere, “to close or shut off,” from prae “before” and claudere “to shut”; it means to prevent something from happening.',C('preclude.s1','排除；阻止','The contract’s strict deadline does not preclude an appeal, but it requires the applicant to file one within ten days.','合同规定了严格期限，但并未排除上诉；申请人须在十天内提出。','The deadline does not preclude an appeal / but it requires the applicant / to file within ten days.','preclude 表示阻止、排除某种可能或行动。','上诉仍可进行，只是必须满足期限条件。'),M('The contract precludes an appeal by explicitly allowing every applicant to appeal at any time without restriction.','The contract precludes a late appeal by requiring every applicant to file within ten days.','允许随时、无限制上诉并没有阻止上诉。','meaning'),[q('What does the contract require for an appeal?','the applicant must file within ten days','the applicant may never appeal','the applicant must summarize the contract in one page','合同要求在十天内提出上诉。',1,'context'),q('What does preclude mean?','prevent something from happening','cause an event to happen suddenly','arrive before someone in a race','preclude 表示阻止或排除。',1,'meaning'),q('Which rule would preclude late applications?','a rule that refuses any form filed after Friday','a rule that accepts forms at any time','a rule that encourages applicants to file late','拒收截止日期后材料的规则会阻止逾期申请。',1,'context'),q('Which Latin parts form praecludere?','prae “before” + claudere “to shut”','prae “before” + currere “to run”','pretium “price” + -ous','praecludere 由“在前”与“关闭”构成。',1,'word-formation')]);
P('precocial','Precocial is a biological term related to Latin praecox, “maturing early,” the same source as precocious; it describes young animals able to see and move soon after hatching or birth.',C('precocial.s1','早成的','Newly hatched precocial ducklings had open eyes and followed their mother across the pond within hours.','刚孵出的早成型小鸭眼睛已睁开，几小时内就跟着母鸭走过池塘。','Newly hatched precocial ducklings / had open eyes / and followed their mother within hours.','precocial 描写出生或孵化后发育较充分、很快能活动的动物幼体。','小鸭睁眼并迅速行走，符合早成型特征。'),M('The ornithologist called the blind, helpless hatchlings precocial even though they could not move or leave the nest.','The ornithologist called the alert ducklings precocial because they could see and walk soon after hatching.','出生后不能睁眼或活动的雏鸟不符合此处早成型描述。','meaning'),[q('What could the ducklings do within hours of hatching?','see and follow their mother across the pond','remain blind and unable to move','build a nest without adult birds','鸭雏孵出后不久就能看见并跟随母鸭。'),q('What does precocial mean in biology?','born or hatched relatively developed and soon able to move','needing prolonged care before opening the eyes','predatory toward all adult animals','precocial 指出生时较成熟、很快能活动。',1,'meaning'),q('Which young animal is precocial?','a chick that hatches alert and walks soon afterward','a hatchling that remains blind and helpless in its nest','an adult bird hunting in a field','孵化后很快能行走的幼鸟符合早成型。',1,'context'),q('Which Latin adjective is related to precocial?','praecox, “maturing early”','praecipitium, “steep place”','praecinctum, “boundary”','precocial 与表示“早熟”的 praecox 有关。',1,'word-formation')]);
P('precocious','Precocious comes from Latin praecox, “maturing early,” formed from prae “before” and coquere “to ripen or cook”; it describes unusually early development.',C('precocious.s1','早熟的','At ten, the precocious pianist could perform a demanding concerto that many older students had not yet mastered.','这位十岁的早熟钢琴家已经能演奏许多年长学生尚未掌握的高难度协奏曲。','The precocious pianist could perform a demanding concerto / at ten / before many older students could.','precocious 指儿童在智力、才能或行为方面超出同龄人的发展水平。','十岁就能演奏高难度曲目，表现出超常早熟。'),M('The teacher called the child precocious because she could not yet recognize letters or complete an age-level task.','The teacher called the child precocious because she mastered advanced music unusually early.','尚未掌握年龄相称的基础能力不能支持“超常早熟”的判断。','meaning'),[q('What could the ten-year-old pianist perform?','a demanding concerto beyond the level of many older students','only a tune she had not practiced','a public vote on a constitution','孩子年纪小却掌握了高难度协奏曲。'),q('What does precocious mean?','unusually advanced for a child’s age','developed later than usual','able to bend without breaking','precocious 指儿童发育或才能超出同龄水平。',1,'meaning'),q('Which child is precocious?','a young learner who reads advanced texts years ahead of age peers','a child who follows the ordinary pace for the age group','a toddler who has not yet begun learning to walk','远超同龄水平的学习表现可称早熟。',1,'context'),q('Which Latin verb contributes to praecox?','coquere, “to ripen or cook”','claudere, “to shut”','cingere, “to surround”','praecox 中 coquere 表示成熟、烹煮。',1,'word-formation')]);
P('preconceive','Preconceive combines pre- “before” with conceive, from Latin concipere; it means to form an idea or judgment in advance, often without evidence.',C('preconceive.s1','事先认为','The review panel tried not to preconceive the result before examining the laboratory data from both teams.','评审小组努力避免在检查两队的实验数据前就预先认定结果。','The panel tried not to preconceive the result / before examining / both teams’ laboratory data.','preconceive 表示在证据出现前预先形成观念或判断。','评审先看数据，避免提前下结论。'),M('The panel preconceived its judgment only after carefully comparing all the evidence and listening to every witness.','The panel preconceived its judgment before reviewing the evidence and hearing the witnesses.','仔细审查证据后才作判断不是预先形成判断。','meaning'),[q('What did the panel try to avoid doing?','forming its judgment before checking the data','comparing evidence from both teams','recording the final result after review','评审小组避免事先认定结果。'),q('What does preconceive mean?','form an idea or judgment in advance','prevent an event from happening','come before another event in time','preconceive 指预先形成想法或判断。',1,'meaning'),q('Which reviewer is preconceiving a conclusion?','one who decides the report is false before reading its evidence','one who waits to read the report before judging it','one who summarizes the report after a careful review','未读证据先认定报告错误，属于预先判断。',1,'context'),q('How is preconceive formed?','pre- “before” + conceive','pre- “before” + cede “go”','pre- “before” + cinch “surround”','preconceive 由 pre- 与 conceive 组成。',1,'word-formation')]);
P('precursor','Precursor came from Latin praecursor, “forerunner,” from praecurrere, “to run ahead,” built from prae “before” and currere “run.”',C('precursor.s1','先驱；先兆','The small battery-powered prototype was a precursor to the lightweight electric buses now used across the city.','这款小型电池原型车是如今全城使用的轻型电动巴士的先驱。','The prototype was a precursor / to the electric buses / now used across the city.','precursor 指在时间上先出现并引向后续发展的人或事物。','早期原型为后来的城市电动巴士提供了先行模型。'),M('The new electric bus was called a precursor to the prototype that had already been built and tested years earlier.','The earlier prototype was a precursor to the new electric bus design.','后来出现的巴士不能成为更早原型的先驱。','meaning'),[q('What was the prototype a precursor to?','the city’s later lightweight electric buses','the city’s earlier horse-drawn carts','a vote on the transport budget','原型车是后来的电动巴士的先驱。'),q('What is a precursor?','something that comes before and leads to a later development','a person who replaces someone in an office','a solid formed in a liquid','precursor 指先出现并引向后续事物的先驱。',1,'meaning'),q('Which could be a precursor to a modern device?','an early working model that led to the later design','a device invented after the current model','an unrelated map of a city district','早期原型推动后续设计，可称为先驱。',1,'context'),q('Which Latin verb contributes to praecursor?','praecurrere, “to run ahead”','praecingere, “to surround”','praecidere, “to cut short”','praecursor 源自 praecurrere“跑在前面”。',1,'word-formation')]);
P('predate','Predate meaning “exist earlier than” combines pre- “before” with date; a separate later verb meaning “hunt prey” arose by back-formation from predator and predation.',C('predate.s1','在时间上早于','The stone foundation predates the wooden house by at least two centuries, according to the survey records.','测绘记录显示，这座石质地基至少比木屋早两百年。','The stone foundation predates the wooden house / by at least two centuries / according to the survey records.','predate.s1 表示在时间上早于某事物。','测绘记录明确指出两者的建造年代差距。'),M('The stone foundation predates the house because it was built two centuries after the house was completed.','The stone foundation predates the house because it was built two centuries earlier.','晚建两百年意味着晚于，不是早于。','meaning'),[q('How much earlier was the foundation built?','at least two centuries before the wooden house','two centuries after the wooden house','at exactly the same time as the house','地基至少早两百年。'),q('What does predate mean here?','come before another thing in time','hunt and eat another animal','make a hasty decision','此处 predate 指时间上早于。',1,'meaning'),q('Which statement is true if the bridge predates the road?','the bridge existed before the road was built','the road existed before the bridge','the bridge and road were built together','桥先于道路存在，符合 predate 的用法。',1,'context'),q('Which pieces form the verb predate in the “earlier than” sense?','pre- “before” + date','pre- “before” + date meaning “hunt”','predator + -ous','时间义 predate 由 pre- 与 date 构成。',1,'word-formation')]);
P('predation','Predation comes from Latin praedatio, “plundering,” from praedari “to take prey”; zoologists use it for hunting in which a predator kills prey for food.',C('predation.s1','捕食','The ecologist tracked predation by recording how often foxes caught rabbits in each section of the reserve.','生态学家通过记录狐狸在保护区各地段捕捉兔子的频率来追踪捕食情况。','The ecologist tracked predation / by recording how often foxes caught rabbits / in each section of the reserve.','predation 指捕食者猎杀猎物作为食物的行为。','狐狸捕捉兔子是捕食行为的实例。'),M('The ecologist defined predation as rabbits growing carrots for food while no animal hunted another.','The ecologist measured predation by recording foxes hunting rabbits for food.','种植蔬菜且没有动物捕猎，不是捕食。','meaning'),[q('What did the ecologist record?','how often foxes caught rabbits','how many carrots rabbits planted','how much rainfall fell on the reserve','生态学家记录狐狸捕捉兔子的频率。'),q('What does predation mean in ecology?','hunting in which a predator kills prey for food','a vote of the entire population','a solid falling out of a solution','predation 指捕食者猎杀猎物作为食物。',1,'meaning'),q('Which observation is evidence of predation?','a hawk catches and eats a mouse','a mouse gathers seeds without being hunted','a fox avoids all other animals','鹰捕捉并吃掉老鼠是捕食行为。',1,'context'),q('Which Latin noun is the source of predation?','praedatio, “plundering or taking prey”','praecinctum, “enclosure”','praecisus, “cut short”','predation 源自拉丁语 praedatio。',1,'word-formation')]);
P('predator','Predator comes from Latin praedator, “plunderer,” from praedari “to rob”; it names an animal that hunts another animal or a person who exploits the vulnerable.',[C('predator.s1','捕食性动物；天敌','A sea-lion predator followed the school of fish until it separated one young fish from the group.','一只海狮捕食者跟随鱼群，直到有一条小鱼与群体分开。','A sea-lion predator followed the school / until one young fish / separated from the group.','predator.s1 指捕食其他动物的动物。','海狮追逐鱼群并准备捕食其中一条鱼。'),C('predator.s2','剥削者；加害弱者的人','The charity warned residents about a financial predator who targeted elderly people with false investment offers.','慈善机构提醒居民提防一名金融剥削者，他用虚假投资项目盯上老年人。','The charity warned residents / about a financial predator / who targeted elderly people.','predator.s2 比喻利用弱者谋取私利的人。','骗子专门利用老年人的信任牟利。')],M('The fish was a predator because it was eaten by a larger fish and never hunted any animal itself.','The larger fish was a predator because it hunted and ate smaller fish.','被捕食且从不捕猎的动物是猎物，不是捕食者。','confusable'),[q('What did the sea-lion predator do?','followed the fish school and pursued a young fish','offered false investments to elderly residents','planted seeds in the reserve','海狮追踪鱼群并捕捉其中的小鱼。',1,'context'),q('Why did the charity call the fraudster a financial predator?','he exploited elderly people through false investment offers','he hunted fish for food','he preceded another officeholder','骗子利用老年人谋私利，属于比喻义 predator。',2,'context'),q('Which animal is a predator?','a hawk that hunts mice','a mouse that is hunted by hawks','a plant that makes its own food','捕猎老鼠的鹰是捕食者。',1,'meaning'),q('Which Latin word is the origin of predator?','praedator, “plunderer”','praecursor, “forerunner”','praecox, “early-ripening”','predator 源自拉丁语 praedator“掠夺者”。',1,'word-formation')]);
P('predatory','Predatory comes from Latin praedatorius, “pertaining to plunder,” from praedator; it describes animal hunting or exploitative behavior toward weaker people.',[C('predatory.s1','捕食性的','The predatory owl waited silently above the meadow before swooping down on a field mouse.','这只捕食性的猫头鹰静静守在草地上方，随后俯冲抓住一只田鼠。','The predatory owl waited above the meadow / before swooping down / on a field mouse.','predatory.s1 形容以捕猎其他动物为生的动物或行为。','猫头鹰猎捕田鼠，体现捕食性。'),C('predatory.s2','掠夺成性的；剥削性的','The regulator fined a predatory lender for hiding extreme fees in contracts offered to struggling borrowers.','监管机构处罚了一家掠夺性贷款机构，因为它向陷入困境的借款人隐瞒高额费用。','The regulator fined a predatory lender / for hiding extreme fees / from struggling borrowers.','predatory.s2 描写利用弱者、以不公平方式牟利的行为。','贷款方隐瞒高额费用并针对困境借款人。')],M('The regulator praised the lender as predatory because it disclosed every fee clearly and offered affordable terms to all borrowers.','The regulator called the lender predatory because it hid extreme fees from vulnerable borrowers.','透明披露费用并提供可负担条款不是剥削性做法。','meaning'),[q('What did the predatory owl hunt?','a field mouse','a lending contract','a sea-lion predator','猫头鹰俯冲捕捉田鼠。',1,'context'),q('Why did the regulator fine the lender?','it hid extreme fees from struggling borrowers','it disclosed all charges and offered fair terms','it measured foxes hunting rabbits','隐瞒高额费用剥削困境借款人。',2,'context'),q('What does predatory mean in “predatory lending”?','designed to exploit vulnerable borrowers','involving careful and transparent pricing','able to move immediately after hatching','predatory lending 指掠夺、剥削借款人的贷款行为。',2,'meaning'),q('Which source noun gives rise to predatory?','predator','precipice','precinct','predatory 源自 predator 与形容词后缀 -y。',1,'word-formation')]);
P('predecessor','Predecessor came through Old French from Late Latin praedecessor, “one who has gone before,” from prae “before” and decessor “retiring official”; it can name a former officeholder or an earlier version of a thing.',[C('predecessor.s1','前任；前辈','The current director thanked her predecessor for organizing the archive and leaving clear records of every project.','现任主任感谢前任整理了档案，并为每个项目留下清晰记录。','The current director thanked her predecessor / for organizing the archive / and leaving clear records.','predecessor.s1 指在同一职位上先于现任者的人。','现任主任接替了此前担任该职位的人。'),C('predecessor.s2','前身；被取代的原有事物','The first portable music player was a predecessor of the smaller digital model released a decade later.','第一款便携音乐播放器是十年后推出的更小型数字机型的前身。','The first portable player was a predecessor / of the smaller digital model / released a decade later.','predecessor.s2 指后来被新事物取代的较早事物。','较早播放器先出现，之后被新机型取代。')],M('The new director was the predecessor of the former director, although she began the job after him.','The former director was the predecessor of the new director because he held the position earlier.','后来上任的人是 successor；前任是先前担任职位的人。','confusable'),[q('Who did the current director thank?','the person who held the director’s position before her','the person who will replace her next year','the author of a one-page précis','主任感谢了此前担任该职位的前任。',1,'context'),q('Why is the first portable player a predecessor of the digital model?','it came earlier and was replaced by the later model','it was invented after the digital model','it was a person who held a job before another','早期机型先于后来的数字机型并被其取代。',2,'context'),q('Which item is a predecessor of a newer product?','an earlier model that the later design replaced','a model released ten years after the current one','a product unrelated to the later design','被后续设计取代的旧型号是前身。',2,'meaning'),q('Which Latin noun contributes to praedecessor?','decessor, “retiring official”','praedator, “plunderer”','praecipitium, “steep place”','praedecessor 中 decessor 指卸任官员。',1,'word-formation')]);
P('predetermine','Predetermine combines pre- “before” with determine; it means deciding or fixing an outcome before the process begins.',C('predetermine.s1','预先决定','The committee agreed not to predetermine the grant winners before reading all of the applications.','委员会同意不要在读完所有申请前就预先决定资助获奖者。','The committee agreed not to predetermine the winners / before reading / all applications.','predetermine 表示在事情开始或证据齐全前预先决定结果。','评审先读申请，避免提前定下获奖者。'),M('The committee predetermine the winning proposal before reviewing any application.','The committee predetermines the winning proposal before reviewing any application.','第三人称单数主语 committee 的一般现在时谓语需加 -s，应使用 predetermines。','grammar'),[q('What did the committee avoid deciding in advance?','which grant applicants would win','how many applications had arrived','which reviewer would read each proposal','委员会避免预先决定获奖者。'),q('What does predetermine mean?','fix an outcome before the process begins','predict a result from reliable evidence','make an exact measurement','predetermine 指提前确定结果。',1,'meaning'),q('Which action would predetermine a contest?','selecting the winner before any entries are judged','scoring each entry and choosing the highest result','publishing the results after the judges finish','比赛评审前先定赢家就是预先决定。',1,'context'),q('How is predetermine formed?','pre- “before” + determine','pre- “before” + dictate “speak”','pre- “before” + dominate “rule”','predetermine 由 pre- 与 determine 组成。',1,'word-formation')]);
P('predetermined','Predetermined is the past participle of predetermine; it describes an outcome or limit settled in advance rather than left to chance.',C('predetermined.s1','业已决定的','The route was predetermined by the safety plan, so the crew could not choose a shorter path through the closed tunnel.','路线已由安全方案预先确定，因此工作人员不能改走封闭隧道中的捷径。','The route was predetermined by the safety plan / so the crew / could not choose another path.','predetermined 描写行动发生前就已确定、并非临时决定的安排。','安全方案已限定路线，现场人员不能随意更改。'),M('The route was predetermined only after the crew finished walking it and chose where they had gone.','The route was predetermined before the crew began, as set out in the safety plan.','路线在走完后才选择并非事先确定。','meaning'),[q('Why could the crew not take a shorter route?','the safety plan had settled the route in advance','the tunnel had never been closed','the crew had not yet begun its journey','安全方案预先确定了路线。'),q('What does predetermined mean?','settled in advance and not left to chance','forecast from evidence but not yet decided','chosen randomly during the action','predetermined 指行动前已定下。',1,'meaning'),q('Which result was predetermined?','a route fixed in the plan before the crew departed','a route selected spontaneously while traveling','a route discovered after the task ended','出发前固定在方案里的路线是预先确定的。',1,'context'),q('Which verb is predetermined derived from?','predetermine','predominate','preen','predetermined 是 predetermine 的过去分词。',1,'word-formation')]);
P('predicament','Predicament came through Medieval Latin predicamentum, first a philosophical “category”; its negative modern sense is an unpleasant or difficult situation.',C('predicament.s1','困境','The hikers’ predicament worsened when the only bridge washed away and their food supplies ran low.','唯一的桥被冲毁、食物也快耗尽后，徒步者的困境更加严重。','The hikers’ predicament worsened / when the bridge washed away / and food ran low.','predicament 指令人不快或难以解决的处境。','失去桥梁且缺少食物使徒步者陷入艰难局面。'),M('The hikers were in a predicament because the bridge was repaired, food was plentiful, and a rescue team had arrived.','The hikers were in a predicament because the bridge was gone and their food was running out.','桥修好、食物充足且救援已到意味着困境已经解除。','meaning'),[q('What worsened the hikers’ predicament?','the bridge washed away and food ran low','a rescue team delivered food and repaired the bridge','the hikers found a plentiful harvest','桥毁且食物减少使困境恶化。'),q('What is a predicament?','a difficult or unpleasant situation','an exact measurement of a distance','a direct vote on an important issue','predicament 指困境或棘手处境。',1,'meaning'),q('Which person is in a predicament?','a traveler stranded by a washed-out bridge with little food','a traveler with a safe road and full supplies','a traveler enjoying an easy walk in mild weather','被困且缺少食物的人处于困境。',1,'context'),q('Which Medieval Latin noun is related to predicament?','predicamentum','praecipitium','praedator','predicament 经 Medieval Latin predicamentum 发展而来。',1,'word-formation')]);
P('predicate','Predicate comes from Latin praedicatum, “that which is said of a subject”; it names the sentence part that says something about the subject, or the verb “assert.”',[C('predicate.s1','谓语','In “The careful technician checked the lens,” the predicate is “checked the lens,” which tells what the technician did.','在“The careful technician checked the lens”中，谓语是“checked the lens”，说明技术员做了什么。','In the sentence / “checked the lens” is the predicate / because it tells what the technician did.','predicate.s1 作语法术语，指说明主语情况的句子成分。','“checked the lens”说出主语做的动作。'),C('predicate.s2','断言；宣称','The report predicates its conclusion on verified measurements rather than on a guess.','报告把结论建立在经核实的测量数据上，而不是猜测上。','The report predicates its conclusion / on verified measurements / rather than on a guess.','predicate.s2 作动词可表示断言，也可见于 predicate A on B“把A建立在B之上”。','结论以已核实数据为依据。')],M('In “The technician checked the lens,” the subject predicate is “the technician,” while “checked the lens” tells what the subject did.','In “The technician checked the lens,” the subject is “the technician” and the predicate is “checked the lens.”','“the technician”是主语；说明主语做什么的部分才是谓语。','grammar'),[q('Which words form the predicate in the example sentence?','checked the lens','the careful technician','the lens only','谓语“checked the lens”说明技术员做了什么。',1,'context'),q('What does the report predicate its conclusion on?','verified measurements','an unsupported guess','a public vote','报告把结论建立在核实过的数据上。',2,'context'),q('What is a predicate in grammar?','the part of a sentence that says something about the subject','the person or thing the sentence describes only','a short summary of a report','predicate.s1 指说明主语情况的部分。',1,'meaning'),q('Which Latin form is the source of predicate as a logic term?','praedicatum, “that which is said of a subject”','praecursor, “forerunner”','praedatorius, “pertaining to plunder”','predicate 与拉丁语 praedicatum“对主语所说之事”有关。',1,'word-formation')]);
P('predict','Predict comes from Latin praedicere, “to say beforehand,” with prae- “before” and dicere “say”; it can state an evidence-based forecast or express an expectation.',[C('predict.s1','预言；预测','Using satellite images and pressure readings, the meteorologist predicted that the storm would turn north before reaching the coast.','气象学家根据卫星图像和气压读数，预测风暴会在抵达海岸前转向北方。','The meteorologist predicted a northward turn / using satellite images / and pressure readings.','predict.s1 指依据知识或证据说出将要发生的事。','预测引用了卫星图像和气压数据作为依据。'),C('predict.s2','预料（某事会发生）','Given the team’s repeated late starts, the coach predicted that they would miss the first checkpoint again.','考虑到队伍屡次迟到，教练预料他们又会错过第一个检查点。','The coach predicted they would miss the checkpoint / given their repeated late starts / again.','predict.s2 可表示认为某种结果很可能发生。','教练从队伍以往的迟到情况推断结果。')],M('The meteorologist predicted the storm’s path by consulting no images, readings, or other evidence and refusing to make a forecast.','The meteorologist predicted the storm’s path from satellite images and pressure readings.','拒绝查看资料且不作预测，与依据数据预测相反。','meaning'),[q('What did the meteorologist predict?','that the storm would turn north before reaching the coast','that the storm had already passed the coast','that the satellite had stopped working','气象学家预测风暴会向北转向。',1,'context'),q('Why did the coach predict the team would miss the checkpoint?','the team had repeatedly started late','the team had never been late','the checkpoint had been removed','教练根据多次迟到预料会再错过检查点。',2,'context'),q('Which statement is an evidence-based prediction?','The pressure readings suggest the storm will turn north.','The storm turned north yesterday, so this is not a forecast.','No evidence exists, but the result is certain.','根据气压资料判断未来路径属于预测。',1,'meaning'),q('Which Latin verb is the source of predict?','praedicere, “to say beforehand”','praecingere, “to surround”','praedari, “to plunder”','predict 源自拉丁语 praedicere“预先说出”。',1,'word-formation')]);
P('predictability','Predictability was formed from predictable + -ity; it names the degree to which an outcome or behavior can be foreseen.',C('predictability.s1','可预测性','The software’s predictability improved after the engineers removed a random delay from the scheduling process.','工程师去掉调度流程中的随机延迟后，软件的可预测性提高了。','The software’s predictability improved / after engineers removed / the random delay.','predictability 指结果或行为可被预先判断的程度。','去掉随机延迟后，系统的输出更容易预料。'),M('The software’s predictability was high because the same input produced a completely different result every time.','The software’s predictability was high because the same input produced the same result reliably.','同一输入每次产生完全不同结果说明难以预测。','meaning'),[q('What change improved the software’s predictability?','removing a random scheduling delay','adding more unpredictable delays','changing the software name','去掉随机延迟后，结果更容易预料。'),q('What does predictability mean?','the degree to which a result can be foreseen','the quality of being unusually early in development','the act of making an outcome impossible','predictability 指结果可预测的程度。',1,'meaning'),q('Which process has high predictability?','one where the same input reliably produces the same output','one where identical inputs lead to unrelated outputs','one where no one records the results','输入相同且结果稳定，说明可预测性高。',1,'context'),q('How was predictability formed?','predictable + -ity','predict + -ful','predator + -ity','predictability 由 predictable 加 -ity 构成。',1,'word-formation')]);
P('predictable','Predictable combines predict with -able; it describes something whose outcome can be forecast.',C('predictable.s1','可预测的；可预料的','Because the tide follows a regular schedule, its level at noon was predictable from the published chart.','由于潮汐按固定时刻变化，根据公布的潮汐表可以预料中午的水位。','Its noon level was predictable / because the tide follows / a regular schedule.','predictable 表示能够根据规律、信息或证据预料。','规律性变化及公开时间表让水位可预料。'),M('The machine’s output was predictable even though identical settings produced a different result on every run.','The machine’s output was predictable because identical settings consistently produced the same result.','设置相同却每次结果不同，说明输出不可预测。','meaning'),[q('Why could the noon tide level be predicted?','the tide followed a regular schedule shown on a chart','the tide changed randomly without any records','the chart described a mountain trail','规律潮汐和潮汐表使中午水位可预料。'),q('What does predictable mean?','able to be forecast','already decided before any process','unusually advanced for one’s age','predictable 指可以预测的。',1,'meaning'),q('Which event is predictable?','a train that arrives at the same published time every day','a machine with random results from identical settings','a sudden event with no pattern or warning','每天按公布时刻到站的列车可预料。',1,'context'),q('Which suffix is added to predict in predictable?','-able','-ance','-ous','predictable 由 predict 加 -able 构成。',1,'word-formation')]);
P('predictably','Predictably is predictable + -ly; it means in a way that follows an expected pattern or character.',C('predictably.s1','可预见地','The battery warning appeared predictably after the device had run for exactly eight hours on the same test cycle.','设备在同一测试循环运行整整八小时后，电量警告如预料般出现。','The warning appeared predictably / after the device had run / for exactly eight hours.','predictably 修饰 appeared，表示结果符合先前可见的规律。','重复的测试循环产生了预料中的警告时间。'),M('The battery warning appeared predictably at random times unrelated to the device’s use or test cycle.','The battery warning appeared predictably after the same eight-hour test cycle.','与使用和测试循环无关的随机时刻不符合“可预料地”。','meaning'),[q('When did the warning appear?','after the device ran for eight hours','before the device was turned on','at a random time unrelated to use','警告按重复测试的规律在八小时后出现。'),q('What does predictably mean?','as one would expect from an established pattern','in a way that cannot be forecast','with unusually careful attention to detail','predictably 指符合可预期规律地。',1,'meaning'),q('Which sentence uses predictably?','The old printer predictably jammed after the same overloaded job.','The printer predictably worked once and then never again for no reason.','Predictably is an adjective describing the machine.','规律性卡纸属于可预见的结果，predictably 修饰 jammed。',1,'grammar'),q('Which adjective is predictably based on?','predictable','predatory','preeminent','predictably 由 predictable 加 -ly 构成。',1,'word-formation')]);
P('prediction','Prediction came from French prédiction and Medieval Latin predictio, from Latin praedicere “say beforehand”; it is a statement about what will happen.',C('prediction.s1','预言；预测','The engineer’s prediction that the bridge would vibrate in strong winds was recorded before the stress test began.','工程师关于大风中桥梁会振动的预测，在压力测试开始前就已记录。','The engineer’s prediction was recorded / before the stress test / began.','prediction 指对未来事件或结果作出的陈述。','陈述在测试前提出，内容指向未来结果。'),M('The report labeled a prediction that the bridge had already collapsed yesterday, although that statement described only a completed past event.','The report labeled a prediction that the bridge would vibrate when the wind test began.','已发生的过去事实是记录或报告，不是对未来的预测。','meaning'),[q('What did the engineer predict about the bridge?','it would vibrate in strong winds','it had already collapsed before the test','it would be used as a polling precinct','工程师预测大风会使桥梁振动。'),q('What is a prediction?','a statement about what will happen','a statement only about a completed past event','a small district defined for voting','prediction 是关于未来会发生什么的陈述。',1,'meaning'),q('Which sentence is a prediction?','The sensors will detect movement when the strong wind arrives.','The sensors recorded movement yesterday.','The bridge is a structure across the river.','第一句说明未来可能发生的情况。',1,'context'),q('Which Latin verb is related to prediction?','praedicere, “to say beforehand”','praedari, “to plunder”','praecurrere, “to run ahead”','prediction 与 praedicere“预先说出”有关。',1,'word-formation')]);
P('predictive','Predictive is formed from predict + -ive; it means able to forecast an outcome or to indicate what is likely to happen.',C('predictive.s1','预测的；预示的','The team found that early pressure changes were predictive of a storm’s later path along the coast.','团队发现，早期气压变化能够预测风暴之后沿海岸的路径。','Early pressure changes were predictive / of the storm’s later path / along the coast.','predictive 描写可用于预测结果或显示可能性的特征。','早期气压变化为后续风暴路径提供预测信号。'),M('The pressure reading was predictive because it revealed nothing about the storm and could not be connected to any later outcome.','The pressure reading was predictive because it helped forecast the storm’s later path.','完全不提供未来信息的读数不能称为预测性的。','meaning'),[q('What were the pressure changes predictive of?','the storm’s later path along the coast','the storm’s path centuries earlier','the number of polling districts','气压变化可预示风暴之后的路径。'),q('What does predictive mean?','able to forecast or indicate a likely outcome','already fixed in advance and impossible to change','full of excessive statistics','predictive 指可预测或预示结果的。',1,'meaning'),q('Which information is predictive of equipment failure?','a rising vibration pattern that often appears before breakdowns','a label added after the machine is discarded','a random number unrelated to machine behavior','经常先于故障出现的振动变化可用于预测故障。',1,'context'),q('Which suffix is used in predictive?','-ive','-ity','-ly','predictive 由 predict 加 -ive 构成。',1,'word-formation')]);
P('predilection','Predilection came through French from Medieval Latin praedilectio, from praediligere “prefer before others,” with prae “before” and diligere “choose, love.”',C('predilection.s1','偏爱','Her predilection for quiet historical novels showed in the books she borrowed from the library each month.','她对安静风格历史小说的偏爱，从每月借阅的书中显而易见。','Her predilection for historical novels / showed in the books / she borrowed each month.','predilection 指在选择中反复显露出的偏好。','她持续选择同一类小说，表明有稳定偏爱。'),M('The reader showed a predilection for historical novels by refusing to borrow or read any of them.','The reader showed a predilection for historical novels by choosing them month after month.','反复拒绝选择某类书，不能表明对它有偏爱。','meaning'),[q('What revealed her predilection?','the historical novels she borrowed each month','the books she consistently refused to read','a map of the library precinct','每月借历史小说显示了她的偏爱。'),q('What does predilection mean?','a preference that repeatedly appears in someone’s choices','a tendency to prevent an event','an exact measure of a result','predilection 指反复体现在选择中的偏爱。',1,'meaning'),q('Which behavior shows a predilection for gardening?','choosing gardening books and activities repeatedly','avoiding every garden and gardening book','making a single accidental purchase','持续选择园艺活动说明有此偏好。',1,'context'),q('Which Latin verb is at the root of praedilectio?','prediligere, “to prefer before others”','praedicere, “to say beforehand”','praedari, “to plunder”','predilection 来自表示“优先选择”的 prediligere。',1,'word-formation')]);
P('predispose','Predispose combines pre- with dispose; the verb means to incline someone in advance or make a later result more likely, mentally or physically.',C('predispose.s1','使易患；使预先有倾向','A family history of the condition may predispose a person to develop it, although it does not make the illness certain.','家族病史可能使人更容易患上这种病，但并不意味着一定会发病。','A family history may predispose a person / to develop the condition / without making it certain.','predispose 表示预先造成倾向或易感性，不等于确定结果。','风险增加了，但句子明确说明并非必然患病。'),M('A family history predisposes every relative to develop the illness with certainty, so no other factors can matter.','A family history may predispose relatives to the illness, but it does not guarantee that they will develop it.','易感倾向不等于必然患病，也不能排除其他因素。','meaning'),[q('What may a family history do?','make a person more likely to develop the condition','guarantee that every relative will become ill','prevent doctors from studying risk factors','家族病史可能提高患病可能，但不能保证结果。'),q('What does predispose mean?','incline someone beforehand or make an outcome more likely','settle an outcome so it cannot change','state a forecast based on evidence','predispose 指预先造成倾向或提高可能性。',1,'meaning'),q('Which factor could predispose a person to a reaction?','a known sensitivity that raises the likelihood of reacting','a guarantee that the reaction has already happened','a random event unrelated to the person','已知过敏敏感性会增加反应的可能。',1,'context'),q('How is predispose formed?','pre- “before” + dispose','pre- “before” + dictate','pre- “before” + plod','predispose 由 pre- 加 dispose 构成。',1,'word-formation')]);
P('predisposition','Predisposition combines pre- with disposition; it names an existing mental inclination or physical susceptibility.',C('predisposition.s1','倾向；易感性','The screening program considered a genetic predisposition to the disease alongside age and environmental exposure.','筛查项目把遗传易感性与年龄、环境暴露一并考虑。','The program considered a genetic predisposition / alongside age / and environmental exposure.','predisposition 指已经存在的心理倾向或身体易感性。','遗传条件会改变风险，但需与其他因素一并评估。'),M('The screening team treated a predisposition as proof that the disease had already developed in every person.','The screening team treated a predisposition as a risk tendency, not as proof of present illness.','易感倾向说明风险，不是疾病已发生的证据。','meaning'),[q('What other factors did the screening program consider?','age and environmental exposure','only whether the disease was already diagnosed','the number of story plots in a report','项目还考虑年龄和环境暴露。'),q('What does predisposition mean?','an existing inclination or susceptibility','an outcome settled in advance','a preference for a particular book','predisposition 指先已存在的倾向或易感性。',1,'meaning'),q('Which case shows a physical predisposition?','a person whose inherited trait raises a health risk','a person certain to develop the condition today','a person who has no relevant risk factor','遗传特征提高健康风险体现易感倾向。',1,'context'),q('Which base noun is used in predisposition?','disposition','prediction','predicament','predisposition 由 pre- 加 disposition 构成。',1,'word-formation')]);
P('predominance','Predominance is predominant + -ance; it names the condition of having greater power, influence, or prevalence than others.',C('predominance.s1','主导地位','The predominance of electric buses on the new route became clear when nearly every scheduled vehicle was battery-powered.','新线路上电动巴士的主导地位十分明显，因为几乎所有班次都由电池驱动。','The predominance of electric buses / became clear / when nearly every vehicle was battery-powered.','predominance 指某事物在数量或影响力上占主导。','大多数班次使用电动巴士，体现其数量优势。'),M('The predominance of electric buses was obvious because nearly every route used only diesel vehicles.','The predominance of electric buses was clear because nearly every route used battery-powered vehicles.','几乎全为柴油车并不能证明电动巴士占主导。','meaning'),[q('What showed the predominance of electric buses?','nearly every scheduled vehicle on the route used a battery','nearly every scheduled vehicle used diesel','the city had no bus route at all','大多数班次采用电动巴士，显示其占主导。'),q('What does predominance mean?','the fact of being most common or most powerful','the ability to bend without breaking','a summary of a long report','predominance 指数量或力量上占主导。',1,'meaning'),q('Which group has predominance?','a group supplying almost all vehicles on the route','a group supplying one vehicle among hundreds','a group with no influence or members','几乎提供全部车辆的群体占主导。',1,'context'),q('Which adjective forms the noun predominance?','predominant','predicative','preeminent','predominance 由 predominant 加 -ance 构成。',1,'word-formation')]);
P('predominant','Predominant came through French from Medieval Latin praedominans, “ruling or exerting influence,” from prae “before” and dominari “rule”; it can mean most powerful or most common.',[C('predominant.s1','占主导地位的','The predominant faction controlled the committee agenda and had enough votes to pass its proposal.','占主导地位的派别控制了委员会议程，并拥有足够票数通过提案。','The predominant faction controlled the agenda / and had enough votes / to pass its proposal.','predominant.s1 强调权力、重要性或影响力高于其他者。','派别控制议程并掌握多数票，体现权力优势。'),C('predominant.s2','主要的；突出的','In the coastal village, the predominant sound at dawn was the call of gulls rather than traffic.','在这座海滨村庄，黎明时最突出的声音是海鸥叫声，而不是交通噪音。','The predominant sound at dawn / was the call of gulls / rather than traffic.','predominant.s2 可指某处或群体中最常见、最显著的事物。','海鸥声比交通声更常听到、更突出。')],M('The faction was predominant because it had no votes, no influence, and no role in setting the agenda.','The faction was predominant because it controlled the agenda and held enough votes to pass proposals.','没有票数或影响力的派别不占主导地位。','meaning'),[q('How did the faction show it was predominant?','it controlled the agenda and held enough votes','it had no votes or role in the committee','it was rarely present at meetings','控制议程和掌握票数体现主导权。',1,'context'),q('What was the predominant sound at dawn?','the call of gulls','the sound of heavy traffic','the ringing of a courthouse bell','海鸥叫声是当地黎明时最突出的声音。',2,'context'),q('What does predominant mean in the village description?','most common or noticeable','the most powerful political faction','able to forecast the weather','此处指最常见或最突出的。',2,'meaning'),q('Which Latin verb contributes to praedominare?','dominari, “to rule”','dicere, “to say”','currere, “to run”','predominant 的拉丁词源含 dominari“统治”。',1,'word-formation')]);
P('predominantly','Predominantly is predominant + -ly; it means for the most part or with one element clearly in the majority.',C('predominantly.s1','主要地；占绝大多数地','The neighborhood is predominantly residential, with only a few shops along its main street.','这个街区主要是住宅区，只有主街沿线有少量商店。','The neighborhood is predominantly residential / with only a few shops / along its main street.','predominantly 修饰 residential，说明该地区大部分用途是居住。','少数商店与大量住宅形成明显比例差异。'),M('The neighborhood is predominantly residential even though almost every building is a factory and no homes are present.','The neighborhood is predominantly residential because most buildings are homes and only a few are shops.','几乎全是工厂且没有住宅，不可能主要是住宅区。','meaning'),[q('What is the neighborhood predominantly used for?','housing','heavy industry','public voting','街区大部分建筑为住宅。'),q('What does predominantly mean?','for the most part; in the majority','in a hasty and careless way','with exact measurement','predominantly 表示主要地、占大多数地。',1,'meaning'),q('Which town is predominantly agricultural?','one where most land is used for farms','one with a single small garden and many factories','one where nobody grows crops','大部分土地用于农场说明以农业为主。',1,'context'),q('Which adjective is predominantly based on?','predominant','predictable','predatory','predominantly 由 predominant 加 -ly 构成。',1,'word-formation')]);
P('predominate','Predominate comes from Medieval Latin praedominare, from prae “before” and dominari “rule”; it means to be greatest in number or to exert the strongest influence.',[C('predominate.s1','占多数；居多','During the survey, native oak trees predominated over planted maples in every section of the reserve.','调查发现，保护区每个地段的本地橡树数量都多于人工种植的枫树。','Native oaks predominated over planted maples / in every section / of the reserve.','predominate.s1 指在群体中数量居多。','每个地段橡树都比枫树多。'),C('predominate.s2','占优势；起主导作用','Although several teams contributed ideas, the safety concerns predominated in the final design discussion.','虽然多个团队都提出了想法，但安全问题在最终设计讨论中起主导作用。','Safety concerns predominated / in the final design discussion / despite several teams’ ideas.','predominate.s2 指在影响或重要性上胜过其他因素。','最终讨论主要受安全考虑支配。')],M('Maples predominated over oaks in the survey even though every section contained more oak trees than maples.','Oaks predominated over maples because the survey counted more oak trees in every section.','每个地段橡树都更多，就不可能是枫树占多数。','meaning'),[q('Which trees predominated in the reserve?','native oaks','planted maples','neither species appeared','保护区各地段本地橡树数量更多。',1,'context'),q('What predominated in the final design discussion?','safety concerns','the number of trees in a reserve','a single participant’s private preference','安全问题在最终讨论中起主导作用。',2,'context'),q('What does predominate.s1 mean?','be the largest in number in a group','exert the strongest influence','be decided before a process begins','predominate.s1 指数量居多。',1,'meaning'),q('Which Latin verb is the root of praedominare?','dominari, “to rule”','dicere, “to say”','diligere, “to choose or love”','predominate 源自拉丁语 dominari“统治”。',2,'word-formation')]);
P('preeminent','Preeminent, also spelled pre-eminent, came from Old French and Latin praeeminens, “rising above”; it describes someone or something surpassing all others in a field.',C('preeminent.s1','杰出的；超群的','The preeminent marine biologist received the award after decades of research that reshaped the field.','这位杰出的海洋生物学家因数十年的研究改变了整个领域而获奖。','The preeminent marine biologist received the award / after decades of research / reshaped the field.','preeminent 表示在特定领域超过其他人或事物。','长期研究对整个学科产生重大影响，体现其杰出地位。'),M('The journal called the newcomer preeminent although the researcher had published no work and was unknown in the field.','The journal called the widely respected researcher preeminent after her influential work transformed the field.','没有成果且未被领域认可，不足以支持“超群杰出”的评价。','meaning'),[q('Why did the biologist receive the award?','decades of influential research reshaped the field','the researcher had never worked in marine biology','the field was a small plot of land','研究改变领域，说明该学者表现杰出。'),q('What does preeminent mean?','surpassing all others in a particular area','most common but unimportant','settled in advance by a committee','preeminent 指在某领域超越其他者。',1,'meaning'),q('Which institution is preeminent?','one recognized as a leader above other institutions in its specialty','one with no record of achievement or expertise','one that only recently opened and has no results','被公认为专长领域领先者的机构可称杰出。',1,'context'),q('Which spelling variant is also used for preeminent?','pre-eminent','preeminentt','predominate','pre-eminent 是 preeminent 的另一种拼写。',1,'spelling')]);
P('preen','Preen comes from Old English preon, a Germanic word; it means a bird smooths its feathers with its beak or a person carefully grooms and takes self-satisfied pride.',[C('preen.s1','整理羽毛；自鸣得意','The sparrow paused on the fence to preen its feathers after the rain, drawing its beak carefully along each wing.','雨后麻雀停在篱笆上整理羽毛，用喙仔细梳理两侧翅膀。','The sparrow paused to preen its feathers / drawing its beak / along each wing.','preen.s1 可指鸟用喙梳理羽毛，也可比喻人精心打扮或自得。','麻雀以喙整理翅羽，使用的是字面义。')],M('The sparrow preened its feathers by using its wings to pull them out and leaving the plumage disordered.','The sparrow preened its feathers by smoothing them with its beak.','用喙梳理羽毛会使羽毛整齐，不会把羽毛拔掉、弄乱。','meaning'),[q('What did the sparrow do after the rain?','smoothed its feathers with its beak','used a tool to plough the fence','made a prediction about the weather','麻雀用喙整理雨后的羽毛。'),q('What does preen mean literally?','smooth or clean feathers with the beak','hunt and eat another animal','close off an area in advance','preen 的字面义是鸟用喙梳理羽毛。',1,'meaning'),q('Which bird is preening?','one drawing its beak along its feathers to clean them','one hunting a mouse across a field','one standing motionless with ruffled feathers','用喙梳理羽毛的鸟正在 preen。',1,'context'),q('Which Old English word is related to preen?','preon','praecox','praedicere','preen 与古英语 preon 有关。',1,'word-formation')]);
P('preexist','Preexist combines pre- “before” with exist; it means to be in existence before another thing or event.',C('preexist.s1','先已存在','The stone tools preexist the village walls, showing that people used the site long before the settlement was built.','这些石器早于村墙存在，说明聚落建成之前人们就已使用该地点。','The stone tools preexist the village walls / showing that people used the site / much earlier.','preexist 表示在另一事物或事件之前已经存在。','工具的年代早于村墙，证明人类更早到过此地。'),M('The stone tools preexist the settlement because archaeologists dated them to several centuries after the village was founded.','The stone tools preexist the settlement because they are several centuries older than its walls.','比聚落晚几个世纪的工具不能说早于聚落存在。','meaning'),[q('What do the stone tools show?','people used the site before the village walls were built','the village was built before anyone visited the site','the walls were used to make a chemical precipitate','石器早于村墙，说明人类更早使用该地点。'),q('What does preexist mean?','already exist before another thing or event','become dominant over a group','form a judgment before seeing evidence','preexist 指先于另一事物存在。',1,'meaning'),q('Which evidence shows that an object preexists a building?','the object is dated centuries earlier than the building','the object was made after the building opened','the object and building have no known dates','器物年代早于建筑，说明其先已存在。',1,'context'),q('How is preexist formed?','pre- “before” + exist','pre- “before” + enclose','pre- “before” + plait','preexist 由 pre- 与 exist 组成。',1,'word-formation')]);
P('prefabricate','Prefabricate combines pre- with fabricate; since the early twentieth century it has meant making sections in a factory before assembling them on site.',C('prefabricate.s1','预先制造','The builder prefabricated the wall panels in a workshop so workers could assemble them quickly at the construction site.','建筑商在车间预先制造墙板，方便工人在施工现场快速组装。','The builder prefabricated the wall panels / in a workshop / for quick assembly on site.','prefabricate 作动词，指先在工厂或车间制造部件，再到现场组装。','墙板先制成，随后才运到工地拼装。'),M('The builder prefabricated the wall panels by making each one from raw concrete at the site after the house was complete.','The builder prefabricated the wall panels in a workshop before assembling them on site.','房屋完工后才在现场制作，不是预先制造部件。','meaning'),[q('Where were the wall panels prefabricated?','in a workshop before delivery to the site','at the site after the house was complete','inside a school polling precinct','墙板在车间预制后再运到工地。'),q('What does prefabricate mean?','make parts in advance before assembling them on site','decorate a completed building after it opens','choose one building design over another','prefabricate 指预先制造部件。',1,'meaning'),q('Which crew prefabricates a structure?','one that makes building sections in a factory, then assembles them on site','one that begins and finishes every part at the final location','one that writes a preface to the building plan','先工厂制造、后现场拼装属于预制。',1,'context'),q('How is prefabricate formed?','pre- “before” + fabricate','pre- “before” + predicate','pre- “before” + preen','prefabricate 由 pre- 与 fabricate 构成。',1,'word-formation')]);
P('prefabricated','Prefabricated is the past participle of prefabricate and describes a structure built from parts manufactured in advance rather than made entirely on site.',C('prefabricated.s1','预制构件的','The clinic opened on schedule because its prefabricated rooms arrived ready to connect to the prepared foundation.','诊所按期开放，因为预制房间运到时已经可以直接与准备好的地基连接。','The clinic opened on schedule / because its prefabricated rooms / were ready to connect.','prefabricated 描写由预先制造的部件组装而成的建筑或结构。','房间部件提前做好，运来后即可安装。'),M('The clinic was prefabricated because workers made every wall from raw materials on site after the foundation was poured.','The clinic was prefabricated because its rooms were manufactured in advance and assembled on site.','所有墙体都在现场从原料制作不属于预制。','meaning'),[q('Why did the clinic open on schedule?','its prefabricated rooms arrived ready to connect','all of its walls had to be made from raw materials on site','the foundation was a literary preface','预制房间可以快速连接，因此诊所按期开放。'),q('What does prefabricated describe?','built from parts manufactured in advance','built entirely from raw materials on site','settled before a process begins','prefabricated 指部件预先制造的。',1,'meaning'),q('Which building is prefabricated?','one assembled on site from factory-made sections','one whose every part is first made on its final site','one made only of temporary tents','工厂制作部件、现场组装的建筑是预制建筑。',1,'context'),q('Which verb is prefabricated derived from?','prefabricate','prefigure','prefer','prefabricated 是 prefabricate 的过去分词。',1,'word-formation')]);
P('preface','Preface comes from Latin praefatio, “fore-speaking,” from praefari “say beforehand”; it names introductory remarks or the act of introducing a subject.',[C('preface.s1','序言；前言','In the preface, the author explains why she collected the letters and thanks the families who preserved them.','作者在前言中解释了收集这些信件的原因，并感谢保存信件的家庭。','In the preface / the author explains her purpose / and thanks the families.','preface.s1 作名词，指书籍开头的介绍性文字。','作者在正文开始前交代写作目的和致谢。'),C('preface.s2','以……为开端；作开场白','The chair prefaced the budget discussion with a brief account of last year’s spending.','主席以简短回顾去年的开支作为预算讨论的开场。','The chair prefaced the discussion / with a brief account / of last year’s spending.','preface.s2 作动词，表示在主要内容前先说或写一段引言。','简短介绍先于预算讨论。')],M('The author called the appendix the preface because it appeared after the final chapter and contained the book’s conclusion.','The author called the opening note the preface because it introduced the book before the chapters began.','出现在书末、总结全书的文字不是前言。','meaning'),[q('What did the author explain in the preface?','why she collected the letters and whom she thanked','the final conclusion after all chapters','how to cast a chemical precipitate','作者在前言中交代收集信件的缘由并致谢。',1,'context'),q('How did the chair preface the budget discussion?','with a short account of last year’s spending','by ending the discussion with next year’s result','by asking the audience to predict a storm','主席先简短回顾上一年的开支。',2,'context'),q('What is a preface.s1?','introductory text at the beginning of a book','the final chapter of a book','the sentence part that describes the subject','preface.s1 指书籍开头的序言。',1,'meaning'),q('Which Latin verb is related to praefatio?','praefari, “to say beforehand”','praeficere, “to place in charge”','praeferre, “to carry before”','preface 源自 praefatio，与 praefari“预先说”相关。',1,'word-formation')]);
P('prefect','Prefect came through French from Latin praefectus, “one placed in authority”; in this source entry it is a student given responsibility over other pupils.',C('prefect.s1','学长；级长','The prefect reminded younger students to leave the science building before the evening alarm test.','级长提醒低年级学生在晚间警报测试前离开科学楼。','The prefect reminded younger students / to leave the building / before the alarm test.','prefect.s1 指在学校中受委任、对其他学生有一定管理职责的学生。','级长负责向低年级学生传达学校要求。'),M('The school appointed a new prefect to follow all instructions from the younger pupils and give them authority over the teachers.','The school appointed a senior student as prefect to help supervise younger pupils.','级长被赋予对学生的职责，而不是由低年级学生管理教师。','meaning'),[q('What did the prefect remind younger students to do?','leave the science building before the alarm test','start the alarm test without permission','write a summary of the science lesson','级长提醒学生及时离开科学楼。'),q('What is a school prefect?','a student given authority or responsibility over other students','a teacher who writes a book’s preface','a person who repairs a plough','prefect 指有管理职责的学生。',1,'meaning'),q('Which student could be a prefect?','a senior pupil assigned to help supervise others','a visitor with no school role','a pupil who is forbidden to give reminders','受委任协助管理其他学生的高年级学生可任 prefect。',1,'context'),q('Which Latin word is related to prefect?','praefectus, “one placed in authority”','praefatio, “fore-speaking”','praedilectio, “preference”','prefect 源自表示“被置于权位者”的 praefectus。',1,'word-formation')]);
P('prefer','Prefer came directly or through French from Latin praeferre, “place or carry before”; it means choosing one thing more, or wanting one action rather than another.',[C('prefer.s1','更喜欢；宁可','I prefer the quieter reading room because its windows face the garden instead of the busy street.','我更喜欢安静的阅览室，因为它的窗户朝向花园，而不是繁忙的街道。','I prefer the quieter reading room / because its windows face / the garden instead of the street.','prefer.s1 表示相比其他选项更喜欢某一项。','说话者在两个阅览环境中选择更安静的一间。'),C('prefer.s2','宁愿（做某事）','When the road is icy, the driver prefers to wait for daylight rather than risk crossing the mountain pass at night.','道路结冰时，司机宁愿等天亮，也不愿冒险夜间穿越山口。','The driver prefers to wait for daylight / rather than risk crossing / the pass at night.','prefer.s2 常用 prefer to do A rather than do B 表示宁愿做A而不做B。','司机在等待天亮和夜间冒险之间作出选择。')],M('I prefer the garden room because I like the noisy street room much more and would choose it instead.','I prefer the garden room because I like its quiet view more than the noisy street room.','理由说喜欢另一间更多，与 prefer 的选择相矛盾。','context'),[q('Why does the speaker prefer the garden-facing room?','it is quieter and faces the garden','it is noisier and faces the busy street','it is the only room with a preface','说话者选择更安静、朝花园的阅览室。',1,'context'),q('What does the driver prefer to do on an icy night?','wait for daylight rather than cross the pass at night','cross the pass at night rather than wait','predetermine which road another driver will choose','司机宁愿等到天亮。',2,'context'),q('Which pattern expresses “宁愿做A而不做B”?','prefer to wait rather than risk crossing','prefer waiting than risk to cross','prefer that wait rather crossing','prefer to do A rather than do B 表示宁愿做A。',2,'grammar'),q('Which Latin verb is the source of prefer?','praeferre, “to place before”','praefari, “to say beforehand”','praediligere, “to choose before others”','prefer 源自 praeferre“置于前面”。',1,'word-formation')]);
P('preferable','Preferable comes through French from prefer; it means better or more desirable than another choice in a particular comparison.',[C('preferable.s1','更好的；更可取的','For the fragile glass, a padded case is preferable to a loose cardboard box during the long shipment.','长途运输易碎玻璃时，带衬垫的箱子比松散的纸板箱更可取。','A padded case is preferable / to a loose cardboard box / for the fragile glass.','preferable.s1 常表示某选项更适合或更好。','有衬垫的箱子能更好保护玻璃。'),C('preferable.s2','更合意的','If you can choose any date, a weekday morning is preferable because the clinic is less crowded then.','如果日期可以任选，工作日早晨更合意，因为那时诊所人少。','A weekday morning is preferable / because the clinic / is less crowded then.','preferable.s2 强调特定情境中更令人满意、更合意的选择。','人少使工作日上午更符合来访者偏好。')],M('A loose box with no padding was preferable for fragile glass because it let the pieces collide throughout the journey.','A padded case was preferable for the fragile glass because it protected the pieces during shipment.','没有衬垫的箱子让玻璃相撞，并非更适合运输。','meaning'),[q('Why is a padded case preferable for the glass?','it better protects fragile pieces during shipment','it lets the glass move and collide freely','it makes the clinic less crowded','衬垫能保护易碎玻璃，因此更适合运输。',1,'context'),q('Why is a weekday morning preferable for the clinic visit?','the clinic is less crowded then','the clinic is always closed then','the patient must prefigure the appointment','较少拥挤使工作日上午更合意。',2,'context'),q('Which option is preferable for carrying hot soup?','a sealed, heat-safe container','an open paper bag that leaks','a thin unsealed envelope','能密封且耐热的容器更适合装热汤。',1,'meaning'),q('Which word is preferable derived from?','prefer','prefect','preen','preferable 源自 prefer。',1,'word-formation')]);
P('preferably','Preferably is preferable + -ly; it introduces the option someone would choose if possible.',C('preferably.s1','最好；更可取地','Please submit the signed form by Friday, preferably as a scanned PDF attached to the email.','请在周五前提交签字表格，最好以扫描后的PDF作为邮件附件。','Please submit the form by Friday / preferably as a scanned PDF / attached to the email.','preferably 用于说明优先选择的方式或条件。','句子先给出截止日，再推荐更理想的文件形式。'),M('Please submit the signed form preferably after the deadline, because submitting it earlier is required.','Please submit the signed form by Friday, preferably as a scanned PDF before the deadline.','要求截止日前提交，却说最好逾期提交，指令前后矛盾。','context'),[q('How should the form preferably be submitted?','as a scanned PDF attached to the email','as an unsigned paper left after Friday','as a one-page precis with no signature','推荐通过邮件附上扫描PDF提交。'),q('What does preferably mean?','in the way or under the condition someone would choose if possible','in a way that is already fixed and cannot change','with exact measurements','preferably 表示最好、若可选择则更倾向于。',1,'meaning'),q('Which sentence uses preferably correctly?','Bring a notebook, preferably one with numbered pages.','Bring preferably a notebook number pages.','Preferably means the notebook is already preferred by everyone.','preferably 自然修饰 one with numbered pages，推荐一种选择。',1,'grammar'),q('Which adjective is preferably based on?','preferable','predetermined','preindustrial','preferably 由 preferable 加 -ly 构成。',1,'word-formation')]);
P('preference','Preference came from Old French preference and Medieval Latin preferentia, from Latin praeferre “place before”; it names a greater liking for one thing over another.',C('preference.s1','偏好；偏爱','The survey recorded each commuter’s preference for train, bicycle, or bus travel before the city redesigned the route.','城市重新规划路线前，调查记录了每位通勤者对火车、自行车或公交的偏好。','The survey recorded each commuter’s preference / for train, bicycle, or bus / before redesigning the route.','preference 指对一种选择胜过其他选择的偏爱。','通勤者在三种出行方式之间表达了更喜欢哪一种。'),M('The survey showed a preference for bicycles even though every commuter chose the train and nobody selected a bicycle.','The survey showed a preference for bicycles because most commuters chose them over the other options.','无人选择自行车，不能说调查显示对自行车的偏好。','meaning'),[q('What choices did the commuter survey compare?','train, bicycle, and bus travel','prefaces, predicates, and predictions','three types of factory-made wall','调查比较了三种通勤方式。'),q('What does preference mean?','a greater liking for one option than another','a statement about what will happen','a measure of exactness','preference 指对一个选项更喜欢。',1,'meaning'),q('Which result shows a preference for cycling?','most respondents choose bicycles over buses and trains','no respondent chooses a bicycle','every respondent refuses to answer','多数受访者选择自行车说明有此偏好。',1,'context'),q('Which Latin verb underlies preference?','praeferre, “to place before”','praefari, “to speak before”','praecidere, “to cut short”','preference 源自 praeferre“置于前面”。',1,'word-formation')]);
P('preferential','Preferential is formed from preference + -al; it describes treatment, rates, or access that favors a particular person or group.',C('preferential.s1','优先的；特惠的','The city offered preferential bus passes to residents who qualified for the low-income support program.','市政府向符合低收入援助计划条件的居民提供优惠公交卡。','The city offered preferential bus passes / to residents / in the support program.','preferential 描写给予某一群体优先或优惠待遇。','符合援助条件的居民获得了额外优惠。'),M('The city called the bus pass preferential although every resident paid the same full fare and received identical access.','The city offered preferential fares to eligible residents, giving them a lower price than other riders.','人人支付相同票价且待遇相同，不是优惠待遇。','meaning'),[q('Who received preferential bus passes?','residents eligible for the low-income support program','every visitor to the city without conditions','only the bus drivers','优惠卡提供给符合援助条件的居民。'),q('What does preferential describe?','treatment or access that favors a particular group','a decision made before any process','a summary placed at the beginning of a book','preferential 指偏向某群体的优惠待遇。',1,'meaning'),q('Which rate is preferential?','a lower transit fare reserved for qualifying students','the same fare charged to every passenger','a price that no passenger can access','专供符合条件学生的较低票价是优惠价。',1,'context'),q('Which noun is preferential built from?','preference','preface','precipitation','preferential 由 preference 加 -al 构成。',1,'word-formation')]);
P('preferentially','Preferentially is preferential + -ly; it means by favoring one choice, person, or group over others.',C('preferentially.s1','优先地','The booking system assigns accessible rooms preferentially to guests who request them for mobility reasons.','预订系统会优先把无障碍房间分配给因行动需要提出申请的客人。','The system assigns accessible rooms preferentially / to guests / who request them for mobility reasons.','preferentially 修饰 assigns，表示按照优先顺序给予特定群体。','申请者因行动需要被优先安排无障碍房间。'),M('The hotel assigned accessible rooms preferentially to guests who did not request them, while rejecting every guest who needed one.','The hotel assigned accessible rooms preferentially to guests who requested them for mobility reasons.','优先分配给不需要者并拒绝有需要者，与优先照顾目标群体相反。','meaning'),[q('Who receives accessible rooms preferentially?','guests who request them for mobility reasons','guests who have no need for them','guests who arrive after the hotel closes','有行动需要并提出申请的客人优先获分配。'),q('What does preferentially mean?','by favoring one option or group over others','in a way that is equally random for everyone','in an exact and measurable manner','preferentially 指优先地、偏向性地。',1,'meaning'),q('Which policy allocates resources preferentially?','reserve the limited accessible rooms first for guests who need them','assign rooms randomly without considering requests','give all accessible rooms to guests who do not need them','根据需求优先留房体现 preferentially。',1,'context'),q('Which adjective is preferentially formed from?','preferential','preindustrial','preeminent','preferentially 由 preferential 加 -ly 构成。',1,'word-formation')]);
P('preferred','Preferred is the past participle of prefer; as an adjective it means selected as the better or official choice among alternatives.',C('preferred.s1','首选的','The preferred entrance for wheelchair users is the ramp beside the east doors, not the steep service steps.','轮椅使用者的首选入口是东门旁的坡道，而不是陡峭的服务台阶。','The preferred entrance / is the ramp beside the east doors / not the service steps.','preferred 表示在多个选择中被选为更合适或官方推荐的。','坡道符合无障碍需求，因此被推荐。'),M('The preferred route for wheelchair users was the steep staircase, while the accessible ramp was marked closed and unsuitable.','The preferred route for wheelchair users was the accessible ramp beside the east doors.','陡峭楼梯不适合轮椅使用者，不能作为推荐路线。','meaning'),[q('Which entrance is preferred for wheelchair users?','the ramp beside the east doors','the steep service steps','the locked freight elevator','坡道是适合轮椅使用者的推荐入口。'),q('What does preferred mean?','selected as the better or official choice','likely to happen based on a pattern','made in a factory before assembly','preferred 指被选为更好的或正式推荐的。',1,'meaning'),q('Which supplier is the preferred one?','the supplier selected after meeting the quality requirements','the supplier that failed every inspection','a supplier not yet considered','符合质量要求并获选的供应商是 preferred supplier。',1,'context'),q('Which verb is preferred derived from?','prefer','prefigure','preform','preferred 是 prefer 的过去分词。',1,'word-formation')]);
P('prefigure','Prefigure comes from Late Latin praefigurare, from prae- “before” and figurare “form”; it means to serve as an early sign or model of something later.',C('prefigure.s1','预示','The small pilot program prefigured the citywide recycling system that expanded to every neighborhood five years later.','这个小型试点项目预示了五年后扩展到所有街区的全市回收系统。','The pilot program prefigured the later system / that expanded / to every neighborhood.','prefigure 指作为后续事件、风格或事物的早期征兆或模型。','试点项目先行展示了后来全面推广的制度。'),M('The pilot project prefigured the recycling system even though it began five years after the citywide program was completed.','The pilot project prefigured the recycling system because it came first and served as an early model.','晚于全面系统的项目不能预示或先行展示它。','meaning'),[q('What did the pilot program prefigure?','the later citywide recycling system','the city’s earlier bus routes','the result of a poll already completed','试点项目是后来全市回收系统的早期模型。'),q('What does prefigure mean?','serve as an early sign or model of something later','select one option because it is liked more','remove a word part from the end','prefigure 指预示或作为先行模型。',1,'meaning'),q('Which event prefigured a later reform?','a small trial that introduced features later adopted nationwide','a report written after the reform had finished','an unrelated weather forecast','先行试点包含后来改革采用的做法，属于预示。',1,'context'),q('Which Latin verb contributes to praefigurare?','figurare, “to form”','fari, “to speak”','ferre, “to carry”','prefigure 源自 praefigurare，其中 figurare 是“塑形”。',1,'word-formation')]);
P('prefix','Prefix came from Latin praefixus, past participle of praefigere, “fasten before”; in grammar it is a word part added before another word.',C('prefix.s1','前缀','In “unhelpful,” the prefix “un-” changes “helpful” to its opposite meaning.','在“unhelpful”中，前缀“un-”把“helpful”变成相反的意思。','In “unhelpful,” the prefix “un-” / changes “helpful” / to its opposite.','prefix.s1 指加在词根或词前、改变词义的构词成分。','un- 位于 helpful 前并改变词义。'),M('In “unhelpful,” the suffix “un-” appears at the end of the word and changes it to the opposite meaning.','In “unhelpful,” the prefix “un-” appears before the base word and changes its meaning.','un- 位于词首，是前缀，不是后缀。','word-formation'),[q('What does un- do in “unhelpful”?','it appears before helpful and reverses its meaning','it appears after helpful and marks a plural','it names the sentence predicate','un- 在 helpful 前并改变词义。'),q('What is a prefix?','a word part added before another word','a word part added only at the very end','a short introduction to a book','prefix 是加在词前的构词成分。',1,'meaning'),q('Which item contains a prefix?','replay, with re- before play','kindness, with -ness after kind','played, with -ed after play','re- 位于 play 之前，是前缀。',1,'context'),q('Which Latin verb is related to prefix?','praefigere, “to fasten before”','praefari, “to speak beforehand”','praediligere, “to prefer”','prefix 与 praefigere“固定在前”有关。',1,'word-formation')]);
P('preform','Preform combines pre- with form; the verb means to give a material an initial shape before its final processing.',C('preform.s1','预先形成','The factory preforms each plastic blank into a short tube before heating and stretching it into a bottle.','工厂先把每个塑料坯料预制成短管，再加热并拉伸成瓶子。','The factory preforms each blank / into a short tube / before heating and stretching it.','preform 表示在最终加工前先赋予材料一个初步形状。','短管形状先形成，之后还要加热拉伸。'),M('The factory preformed the bottle by shaping the plastic only after every heating and stretching step was finished.','The factory preformed the plastic blank into a short tube before the final heating and stretching.','全部最终加工完成后才成形，不是预先形成初始形状。','meaning'),[q('What shape did the factory give each blank first?','a short tube','a finished glass bottle','a folded fabric pleat','坯料先被预制成短管。'),q('What does preform mean?','give something an initial shape before final processing','assemble finished sections at the final site','select something as the better choice','preform 指最终加工前先塑成初始形状。',1,'meaning'),q('Which manufacturer preforms a part?','one that shapes the blank before heating and finishing it','one that begins shaping only after the product is complete','one that writes a preface to the instructions','先塑坯再完成加工属于预成形。',1,'context'),q('How is preform formed?','pre- “before” + form','pre- “before” + prefer','pre- “before” + flect','preform 由 pre- 与 form 组成。',1,'word-formation')]);
P('prefrontal','Prefrontal combines pre- with frontal and describes the area at the front of the brain associated with planning and self-control.',C('prefrontal.s1','前额叶的','The prefrontal region was active while volunteers compared long-term consequences before choosing between the two options.','志愿者在两个选项间比较长期后果时，前额叶区域处于活跃状态。','The prefrontal region was active / while volunteers compared / long-term consequences.','prefrontal 描写与前额叶皮层有关的区域或活动。','任务要求规划并比较后果，涉及前额叶相关功能。'),M('The prefrontal cortex lies at the back of the brain behind the cerebellum, far from the forehead.','The prefrontal cortex lies near the front of the brain, behind the forehead.','前额叶位于大脑前部，不在小脑后方。','meaning'),[q('What were volunteers doing when the prefrontal region was active?','comparing long-term consequences','ploughing a field','reciting a book’s preface','任务要求比较未来后果。'),q('What does prefrontal mean?','relating to the region at the front of the brain','relating to a period before written history','relating to a word part added at the end','prefrontal 指与大脑前额区域有关的。',1,'meaning'),q('Which study task may involve prefrontal planning?','weighing future consequences before making a choice','measuring rainfall with a gauge','identifying a school prefect','比较未来后果并决策属于规划任务。',1,'context'),q('How is prefrontal formed?','pre- “before/in front” + frontal','pre- “before” + rainfall','pre- “before” + preference','prefrontal 由 pre- 与 frontal 构成。',1,'word-formation')]);
P('pregnancy','Pregnancy is pregnant + -cy; it names the state of having a developing baby in the body.',C('pregnancy.s1','怀孕；妊娠','The clinic scheduled additional checkups during the pregnancy because the patient needed regular monitoring.','由于患者需要定期监测，诊所在妊娠期间安排了额外检查。','The clinic scheduled additional checkups / during the pregnancy / for regular monitoring.','pregnancy 指身体内有胎儿发育的状态或时期。','检查安排针对妊娠期间的健康监测。'),M('The clinic recorded a pregnancy even though the patient had no developing baby and the test confirmed she was not pregnant.','The clinic recorded the pregnancy after the test confirmed that a baby was developing.','检查证实没有怀孕时，不能记录为妊娠。','meaning'),[q('Why did the clinic schedule additional checkups?','the patient needed monitoring during pregnancy','the patient had finished a marathon','the clinic was reviewing a preface','额外检查用于妊娠期间的监测。'),q('What does pregnancy mean?','the state of having a baby developing in the body','a preference between two choices','a period before written records','pregnancy 指怀孕、妊娠状态。',1,'meaning'),q('Which situation is pregnancy?','a developing baby is present and receives prenatal care','a patient has no pregnancy and no prenatal monitoring','a clinic studies the history of an old town','有胎儿发育并接受产前护理属于妊娠。',1,'context'),q('Which adjective is pregnancy formed from?','pregnant','preferential','prefrontal','pregnancy 由 pregnant 加 -cy 构成。',1,'word-formation')]);
P('pregnant','Pregnant comes from Latin praegnantem, “with child,” likely built from prae- “before” and the root of gnasci “be born”; it can also mean full of unstated meaning.',[C('pregnant.s1','怀孕的','The pregnant patient asked the clinic to explain which medicines were safe during the next stage of prenatal care.','这位孕妇请诊所说明产前护理下一阶段哪些药物是安全的。','The pregnant patient asked the clinic / which medicines were safe / during prenatal care.','pregnant.s1 指体内有胎儿发育的。','患者就妊娠期间用药咨询医务人员。'),C('pregnant.s2','意味深长的；耐人寻味的','After a long silence, the detective noticed the witness’s pregnant pause before she answered the question.','长时间沉默后，侦探注意到证人在回答问题前那意味深长的停顿。','The detective noticed a pregnant pause / before the witness answered / the question.','pregnant.s2 可形容充满暗示或意味、但没有明说的表达或停顿。','停顿引人注意，暗示证人可能有所隐瞒。')],M('The pregnant pause was meaningless and revealed nothing, so the detective noticed no significance in it.','The pregnant pause suggested that the witness was withholding something important.','称为“意味深长”的停顿应暗含重要意义，而不是毫无暗示。','meaning'),[q('What did the patient ask the clinic about?','which medicines were safe during pregnancy','how to predict the next storm','how to preform plastic blanks','孕妇咨询妊娠期间的用药安全。',1,'context'),q('What did the detective notice before the answer?','a pregnant pause that seemed meaningful','a regular pause with no possible implication','a preindustrial village map','意味深长的停顿暗示了未说出口的内容。',2,'context'),q('What does pregnant mean in “a pregnant pause”?','full of an unstated meaning','carrying a developing baby','selected as the official choice','这里 pregnant 表示充满暗示、意味深长。',2,'meaning'),q('Which Latin form is related to pregnant?','praegnantem, “with child”','praefixus, “fastened before”','praedecessor, “one who went before”','pregnant 源自拉丁语 praegnantem。',1,'word-formation')]);
P('prehistoric','Prehistoric combines pre- “before” with historic; it describes the period before written history or something from that time.',C('prehistoric.s1','史前的','Archaeologists found prehistoric tools beneath the later village floor, in a layer formed before writing reached the region.','考古学家在后来的村庄地面下发现了史前工具；该地层形成于文字传入此地之前。','Archaeologists found prehistoric tools / in a layer formed / before writing reached the region.','prehistoric 指文字历史记录出现之前的时代或该时代的遗物。','工具所在的年代早于当地文字记录。'),M('The archaeologist called the signed medieval manuscript prehistoric because it was written centuries after records began.','The archaeologist called the unwritten stone tools prehistoric because they predated written records.','有文字记录出现数世纪后的手稿不是史前遗物。','meaning'),[q('Where were the prehistoric tools found?','in a layer formed before writing reached the region','in a modern library after the first books were printed','inside a factory-made plastic tube','工具所在年代早于文字传入当地。'),q('What does prehistoric mean?','from the period before written history','from a period with extensive written records','a decision fixed before an experiment','prehistoric 指文字史之前的时期。',1,'meaning'),q('Which object is prehistoric?','a stone tool from a layer older than local writing','a signed document from a recorded medieval century','a digital archive created last year','没有文字记录时期的石器属于史前遗物。',1,'context'),q('How is prehistoric formed?','pre- “before” + historic','pre- “before” + pregnant','pre- “before” + prefer','prehistoric 由 pre- 与 historic 组成。',1,'word-formation')]);
P('prehistory','Prehistory is pre- “before” + history; it refers to human history before writing or to earlier developments that lead to a present situation.',[C('prehistory.s1','史前史；前史','The museum’s prehistory gallery shows stone tools and pottery from communities that left no written records.','博物馆的史前史展厅展示了没有留下文字记录的社群使用的石器和陶器。','The gallery shows tools and pottery / from communities / that left no written records.','prehistory.s1 指文字出现以前的人类历史。','展品来自尚无文字记录的社群。'),C('prehistory.s1','现状的前期发展','The report traces the prehistory of the merger, including the earlier negotiations that shaped the final agreement.','报告追溯了这次合并的前期发展，包括塑造最终协议的早期谈判。','The report traces the merger’s prehistory / including earlier negotiations / that shaped the agreement.','prehistory 也可比喻指形成当前事态的较早发展过程。','早期谈判先于并影响了最终合并协议。')],M('The museum displayed prehistory as a set of signed newspapers from the period when local writing and archives were already common.','The museum displayed prehistory through tools and pottery made before written records existed.','已有大量文字档案的时期属于有文字的历史，不是史前史。','meaning'),[q('What did the prehistory gallery display?','tools and pottery from communities without written records','signed newspapers from a modern town','the final agreement of a recent merger','展厅展示没有文字记录的社群文物。',1,'context'),q('What did the report trace before the merger?','earlier negotiations that shaped the agreement','events that happened after the agreement was signed','the history of a prehistoric cave only','报告追溯了合并协议形成前的谈判。',1,'context'),q('What does prehistory mean in the museum context?','human history before writing','a period with many written archives','a sentence part that tells about the subject','博物馆语境中的 prehistory 是文字出现前的人类历史。',1,'meaning'),q('Which phrase is a figurative use of prehistory?','the earlier negotiations behind a later merger','a stone tool from before writing','a prehistoric animal fossil','形成后续合并的早期谈判可比喻为其前史。',1,'meaning')]);
P('preindustrial','Preindustrial combines pre- “before” with industrial; it describes societies or economies from before the industrial era.',C('preindustrial.s1','未工业化的','In the preindustrial village, most families grew food locally and goods were made by small workshops rather than factories.','在这个工业化以前的村庄，大多数家庭在当地种植食物，商品由小作坊而不是工厂制作。','In the preindustrial village / families grew food locally / and workshops made most goods.','preindustrial 指工业时代之前的社会或经济。','当地农业和小作坊生产体现工业化以前的生活方式。'),M('The historian called the city preindustrial because its economy depended on large automated factories and mass production.','The historian called the village preindustrial because families farmed locally and goods came from small workshops.','依靠大型自动化工厂和大规模生产属于工业化经济。','meaning'),[q('How were goods made in the preindustrial village?','in small workshops rather than factories','in large automated factories','only by digital printers','村庄商品主要由小作坊制作。'),q('What does preindustrial mean?','from before the industrial era','produced by large-scale factories','made before a particular daily meeting','preindustrial 指工业时代以前的。',1,'meaning'),q('Which economy is preindustrial?','one based mainly on farming and small local workshops','one centered on automated mass-production factories','one that relies only on digital service companies','以农业和小作坊为主的经济属于工业化以前的。',1,'context'),q('How is preindustrial formed?','pre- “before” + industrial','pre- “before” + preference','pre- “before” + incline','preindustrial 由 pre- 与 industrial 构成。',1,'word-formation')]);
P('prejudice','Prejudice comes through Old French from Latin praeiudicium, an advance judgment or harm; the noun names an unfair prior opinion and the verb can mean to harm or bias.',[C('prejudice.s1','偏见；成见','The hiring panel reviewed each application without prejudice based on the candidate’s accent or family background.','招聘小组审阅每份申请时，没有因候选人的口音或家庭背景而产生偏见。','The panel reviewed each application / without prejudice / based on accent or background.','prejudice 可指缺乏充分依据的偏见或成见。','决定不根据口音、家庭背景等预设看法作出。'),C('prejudice.s2','损害；不利影响','Publishing the draft findings too early could prejudice the fairness of the later investigation.','过早公布调查初步结果可能损害后续调查的公正性。','Publishing the draft too early / could prejudice the fairness / of the later investigation.','作动词时 prejudice 可表示损害某事的公正或机会。','过早公开信息会对之后公正调查造成不利影响。'),C('prejudice.s3','使产生偏见','A misleading headline may prejudice readers against the neighborhood before they visit it.','误导性的标题可能使读者在到访之前就对这个社区产生偏见。','A misleading headline / may prejudice readers against the neighborhood / before a visit.','作动词时也可表示使某人对某人或某事产生偏见。','标题先入为主地影响读者对社区的看法。')],M('The panel showed prejudice by judging every applicant only after carefully checking relevant evidence and using the same criteria.','The panel showed prejudice by rejecting applicants because of unsupported assumptions about their backgrounds.','根据未经证实的背景假设作判断才是偏见；认真核查证据并使用同一标准并非如此。','meaning'),[q('What did the panel avoid when it reviewed applicants?','unfair assumptions about accent or background','a careful review of relevant evidence','a consistent selection procedure','小组避免按口音或背景形成偏见。',1,'context'),q('How might early publication affect an investigation?','it could damage the fairness of the later inquiry','it would guarantee a fair outcome','it would remove every earlier finding','过早公布可能损害后续调查的公正。',2,'context'),q('What does prejudice against a neighborhood mean here?','make readers form an unfair opinion before visiting','help readers reserve a place to live','give readers an accurate map of the area','误导标题可能使读者在到访前形成偏见。',3,'meaning'),q('Which origin best explains prejudice?','Latin praeiudicium, an advance judgment or harm','Greek mikros, meaning small','Latin praemium, meaning reward','词源是表示预先判断或损害的拉丁词。',1,'word-formation')]);
P('preliminary','Preliminary comes from Medieval Latin preliminaris, built on Latin prae- “before” and limen “threshold”; it describes an initial step or a qualifying round.',[C('preliminary.s1','初步的；预备的','The team published preliminary results and warned that the full analysis could still change the estimates.','团队公布了初步结果，并提醒完整分析仍可能改变这些估算。','The team published preliminary results / and warned / that estimates could change.','preliminary 作形容词表示正式或完整过程之前的初步阶段。','结果尚待完整分析，因此仍属初步结果。'),C('preliminary.s2','预赛；初步活动','Three runners advanced from the morning preliminary to the evening final.','三名选手从上午的预赛晋级到晚上的决赛。','Three runners advanced / from the morning preliminary / to the evening final.','preliminary 作名词可指决赛前的预赛或前期活动。','上午比赛用于筛选晋级决赛的选手。')],M('The committee called the estimates preliminary because they were the final figures after every audit and revision had ended.','The committee called the estimates preliminary because a full audit and revision were still pending.','完整审计和修订结束后的最终数字不应称为初步估算。','meaning'),[q('Why might the published estimates change?','they are preliminary and the full analysis is unfinished','they are final and no review remains','they were copied from the evening final','结果尚属初步，完整分析可能改变估算。',1,'context'),q('What happened in the morning preliminary?','runners competed for places in the final','the championship ended without a final','the runners received their medals','预赛决定选手能否进入决赛。',2,'context'),q('Which phrase uses preliminary as an adjective?','a preliminary estimate before the full audit','a runner winning the final','the threshold of a doorway','preliminary estimate 是正式结果前的初步估算。',1,'grammar'),q('What does the Latin element limen mean in this origin?','threshold','small','to carry','limen 表示门槛，词源说明它处在正式阶段之前。',1,'word-formation')]);
P('preliterate','Preliterate combines pre- “before” and literate; it describes a society or period in which writing is not yet used.',C('preliterate.s1','文字出现以前的；未使用文字的','Researchers study oral traditions to understand how preliterate communities preserved laws and genealogies.','研究人员研究口述传统，以了解尚未使用文字的社群如何保存法律和世系。','Researchers study oral traditions / to learn how preliterate communities / preserved laws and genealogies.','preliterate 指尚未形成或使用文字记录的社会。','法律和世系借助口述传统而非书写保存。'),M('The archaeologist called the society preliterate because its members maintained extensive written archives and printed books.','The archaeologist called the society preliterate because it preserved knowledge orally before adopting writing.','拥有广泛文字档案和印刷书籍的社会已在使用文字。','meaning'),[q('How did preliterate communities in the example preserve genealogies?','through oral traditions','through printed books','through digital archives','例句说明他们通过口述传统保存世系。'),q('What does preliterate mean?','existing before or without the use of writing','able to read and write fluently','written after an event','preliterate 指文字使用之前或尚未使用文字的。',1,'meaning'),q('Which evidence may help researchers study a preliterate society?','oral accounts passed down between generations','a large collection of its printed newspapers','its online database of written laws','口述资料可帮助研究尚无文字记录的社群。',1,'context'),q('How is preliterate formed?','pre- “before” + literate','pre- “before” + literal “letter” only','pre- “before” + literature “a book”','preliterate 由 pre- 与 literate 构成。',1,'word-formation')]);
P('prelude','Prelude entered English through French from Latin praeludere, “to play beforehand”; it can be a short opening piece of music or an event that leads to a larger one.',C('prelude.s1','序曲；前奏；序幕','A quiet piano prelude opened the recital before the orchestra joined the soloist.','一段安静的钢琴前奏开启了音乐会，随后乐团加入独奏。','A quiet piano prelude opened the recital / before the orchestra joined / the soloist.','prelude 可指较大型音乐作品或演出前的短乐曲，也可比喻为先导事件。','短钢琴曲在正式合奏前演奏。'),M('The orchestra called the final movement a prelude because it came after the entire concert had finished.','The orchestra called the opening piano piece a prelude because it came before the larger performance.','音乐会结束后出现的乐章不能作为它的前奏。','meaning'),[q('What opened the recital?','a quiet piano piece','the final orchestral movement','a spoken weather report','音乐会由一段安静的钢琴前奏开启。'),q('What is a prelude in music?','a short piece played before a larger work or performance','the final movement after a concert','a written review published the next day','prelude 可指大型作品或演出之前的短乐曲。',1,'meaning'),q('Which event could be called a prelude to a campaign?','a small local meeting that happens before the full campaign','the campaign’s final results announcement','a celebration held after the campaign ends','先行的小型会议可以是整个活动的序幕。',1,'context'),q('Which source form is behind English prelude?','Latin praeludere, “to play beforehand”','Greek neuron, “nerve”','Latin praemium, “reward”','prelude 经法语来自表示预先演奏的拉丁词。',1,'word-formation')]);
P('premature','Premature comes from Latin praematurus, “too early,” combining prae- “before” with maturus “ripe”; it means happening before the proper time or born too early.',[C('premature.s1','过早的；未成熟的','The chair called it premature to announce a winner before the independent recount was complete.','独立复核尚未完成，主席认为此时宣布获胜者为时过早。','The chair called it premature / to announce a winner / before the recount was complete.','premature 可表示在适当时间或准备完成以前发生的。','复核未完就宣布结果，时间过早。'),C('premature.s2','早产的；过早出生的','The premature infant remained in the neonatal unit until she could breathe without assistance.','这名早产儿留在新生儿病房，直到能够自行呼吸。','The premature infant remained in the neonatal unit / until she could breathe / without assistance.','premature 也指婴儿在通常预产期之前出生。','婴儿出生过早，需在新生儿病房接受照护。')],M('The director’s announcement was premature because it was made only after every recount and independent check was complete.','The director’s announcement was premature because the recount and independent checks were still unfinished.','所有复核结束后才宣布结果并非过早。','meaning'),[q('Why did the chair delay announcing a winner?','the independent recount was not complete','the result had been checked several times','the next season had already begun','独立复核未完成，宣布结果为时过早。',1,'context'),q('Why was the infant in the neonatal unit?','she had been born before the expected time','she was waiting for an election recount','she was taking part in a musical prelude','例句中的 premature infant 指早产儿。',2,'context'),q('What does premature mean in “a premature announcement”?','made before the proper time','made after a long delay','made without any written words','premature 表示发生或作出得过早。',1,'meaning'),q('Which Latin parts contribute to premature?','prae- “before” + maturus “ripe”','pre- “before” + meter “measure”','micro- “small” + mature “adult”','词源由表示“在前”的 prae- 和“成熟”的 maturus 构成。',1,'word-formation')]);
P('premier','Premier comes from French premier, from Latin primarius and primus “first”; as a noun it often means a prime minister, and as an adjective it means leading or foremost.',[C('premier.s1','总理；首相','The premier addressed the legislature after the cabinet approved the emergency plan.','内阁批准紧急计划后，总理向立法机构发表讲话。','The premier addressed the legislature / after the cabinet approved / the emergency plan.','premier 作名词常指政府首脑，即总理或首相。','该人物在内阁批准计划后向立法机构讲话。'),C('premier.s2','首要的；最重要的','The city’s premier art museum expanded its collection with works from local painters.','这座城市首屈一指的艺术博物馆收藏了更多当地画家的作品。','The city’s premier art museum expanded its collection / with works / from local painters.','premier 作形容词表示首要的、领先的或最重要的。','称博物馆为首屈一指，说明其地位突出。')],M('The newspaper used premier as a noun for the city’s leading museum building, not for the head of government.','The newspaper called the head of government the premier and described the museum as the city’s premier gallery.','表示政府首脑时 premier 是名词；描述领先地位时它作形容词。','grammar'),[q('Who spoke to the legislature?','the head of government','the museum curator','the emergency-plan reviewer','例句中的 premier 是向立法机构讲话的总理。',1,'context'),q('What does premier mean as an adjective?','leading or foremost','born before the expected time','a written assumption','形容词 premier 表示首要或领先的。',2,'meaning'),q('Which usage makes premier a noun?','The premier met the cabinet.','The premier museum opened a new wing.','The premier collection includes local art.','“总理会见内阁”中 premier 是名词。',1,'grammar'),q('Which origin is associated with premier?','French premier from Latin primarius / primus “first”','Latin praemium “reward”','Greek mikros “small”','premier 源于表示“第一”的法语和拉丁语词。',1,'word-formation')]);
P('premiere','Premiere comes from French première, the feminine form of premier “first”; as a noun it is the first public performance or screening of a work.',C('premiere.s1','首映；首演','The documentary’s premiere sold out, and the director answered questions after the screening.','这部纪录片的首映场售罄，放映后导演回答了观众提问。','The documentary’s premiere sold out / and the director answered questions / after the screening.','premiere 指作品首次公开放映或演出，也可作动词表示首映、首演。','该场次是纪录片首次公开放映。'),M('The film’s premiere was its tenth public screening after it had toured cinemas for six months.','The film’s premiere was its first public screening, held before its later cinema tour.','已经巡映六个月的第十场放映不是首映。','meaning'),[q('When did the director answer questions?','after the film’s first public screening','before the documentary was made','during the tenth screening months later','导演在纪录片首映后回答问题。'),q('What is a film premiere?','its first public screening','its final private rehearsal','a review written by the director','premiere 是影片首次公开放映。',1,'meaning'),q('Which event is a premiere?','the first public performance of a new play','a rehearsal held for the cast alone','a repeat screening in its sixth month','新剧首次公开演出是首演。',1,'context'),q('What does the French form première contribute to premiere?','the sense of “first”','the sense of “small”','the sense of “measure”','première 是 premier 的阴性形式，含“第一”之意。',1,'word-formation')]);
P('premise','Premise comes from Medieval Latin praemissa, “a thing placed before”; it can mean an assumption supporting an argument or, in the plural, a building and its grounds.',[C('premise.s1','前提；假设','The argument rests on the premise that every applicant has equal access to the online form.','这一论证以所有申请者都能平等使用在线表格为前提。','The argument rests on the premise / that every applicant has equal access / to the online form.','premise 可指推理或论证所依据的前提、假设。','结论建立在申请者都能平等使用表格这一假设上。'),C('premise.s2','房屋及其附属土地；场所','The fire marshal ordered everyone to leave the premises while the alarm system was inspected.','消防检查报警系统期间，消防官员要求所有人离开该处房屋及其场地。','The fire marshal ordered everyone / to leave the premises / during the inspection.','premises 常用复数形式表示房屋及其附属土地或经营场所。','检查期间人员需离开这处场所。')],M('The conclusion was based on the premise that all applicants had access, although the online form was unavailable to half of them.','The conclusion was based on a premise that all applicants had equal access, and the form was available to everyone.','如果半数申请者无法使用表格，“所有人都能使用”的前提就不成立。','meaning'),[q('What assumption supports the argument?','every applicant can access the online form','the form is unavailable to every applicant','the fire marshal approved the argument','论证的前提是每位申请者都能使用在线表格。',1,'context'),q('What were people ordered to leave?','the building and its grounds','the argument’s conclusion','the online application form','premises 在例句中指需要离开的房屋及场地。',2,'context'),q('Which sentence uses premise as an assumption?','The premise is that every voter received a ballot.','The staff left the premises at closing time.','The premises include the shop and its yard.','关于每位选民都收到选票的陈述是一个假设前提。',1,'grammar'),q('What is the historical sense of Medieval Latin praemissa?','a thing placed before','a thing measured in small units','a reward given afterward','praemissa 的意思是“放在前面的事物”，发展出论证前提义。',1,'word-formation')]);
P('premises','Premises is the plural noun used for a building or group of buildings and the land belonging to them; it is historically the plural of premise.',C('premises.s1','房屋及其附属土地；场所','Visitors must sign in at reception before entering the laboratory premises.','访客进入实验室场地前必须先在接待处登记。','Visitors must sign in / before entering the laboratory premises / at reception.','premises 通常以复数形式指一处房屋、建筑群或经营场所及附属土地。','访客进入实验室场所前需登记。'),M('The guard asked visitors to sign in after they had entered the premises and left the building.','The guard asked visitors to sign in before they entered the premises.','进入场所之后再要求先登记，时间顺序不合逻辑。','context'),[q('What must visitors do before entering the laboratory premises?','sign in at reception','leave their identification at home','inspect the building’s alarm system','访客需在接待处登记后再进入场所。'),q('What does premises mean here?','the laboratory buildings and their grounds','the assumptions behind an argument','the laboratory’s research results','premises 指实验室建筑及其场地。',1,'meaning'),q('Which sentence uses premises correctly?','The shop closed its premises for repairs.','The argument rests on one premises that is untested.','She premise the visitors before the tour.','premises 可指维修期间关闭的店铺场所。',1,'grammar'),q('Which form normally names the physical site?','premises','premise only in the singular','premising','表示物理场所时通常使用复数形式 premises。',1,'grammar')]);
P('premium','Premium comes from Latin praemium, “reward” or “prize”; it can mean an insurance payment, an amount above the usual price, or a superior grade.',[C('premium.s1','保险费；保费','The family paid its annual insurance premium before the renewal deadline.','这家人在续保截止日期前缴纳了年度保险费。','The family paid its annual insurance premium / before the renewal deadline.','premium 可指为保险保障定期缴纳的保险费。','缴纳该笔款项是维持保险保障的条件。'),C('premium.s2','优质的；高档的','The café charges more for its premium coffee, which is made from carefully selected beans.','这家咖啡馆的优质咖啡价格更高，所用咖啡豆经过仔细挑选。','The café charges more / for its premium coffee / made from selected beans.','premium 作定语可表示质量高于普通等级的。','精选咖啡豆和较高价格体现优质等级。'),C('premium.s3','溢价；高价','During the shortage, buyers paid a premium for the few remaining replacement parts.','短缺期间，买家为仅剩的替换零件支付了高价。','During the shortage / buyers paid a premium / for the remaining parts.','premium 也可指超出通常价格的额外金额或溢价。','短缺使稀缺零件售价高于平常。')],M('The buyer paid a premium below the usual price because the scarce replacement parts were cheaper than normal.','The buyer paid a premium above the usual price because the replacement parts were scarce.','premium 在这里是短缺造成的额外高价，而不是低于平常的价格。','meaning'),[q('When did the family pay its insurance premium?','before the renewal deadline','after the policy had expired for a year','only when the café sold coffee','保费在续保截止日期之前缴纳。',1,'context'),q('Why did the café charge more for its premium coffee?','it used carefully selected beans for a higher-grade product','it was selling the cheapest beans available','it was collecting an insurance payment','premium coffee 指优质咖啡，因此价格更高。',2,'context'),q('What did buyers pay during the parts shortage?','an amount above the usual price','a refund below the purchase price','a yearly insurance fee','短缺期间他们为零件支付了溢价。',3,'meaning'),q('Which Latin word is the source of premium?','praemium, meaning “reward” or “prize”','prae, meaning “before,” alone','micro, meaning “small”','premium 来自表示奖赏或奖品的拉丁词。',1,'word-formation')]);
P('preoccupation','Preoccupation derives from Latin praeoccupatio, “a taking possession beforehand”; in English it is absorption in a subject or a persistent worry.',[C('preoccupation.s1','全神贯注；专注','Her preoccupation with the restoration project left little time for other hobbies.','她全神贯注于修复项目，几乎没有时间做其他爱好。','Her preoccupation with the restoration project / left little time / for other hobbies.','preoccupation 可指注意力被某事占据的专注状态。','修复项目占据了她大部分时间和注意力。'),C('preoccupation.s2','挂念；忧虑','The family’s main preoccupation was whether the flood barrier would hold overnight.','这家人最挂心的是防洪堤能否撑过夜晚。','The family’s main preoccupation / was whether the flood barrier / would hold overnight.','preoccupation 也可指持续萦绕心头的担忧。','家人反复担心防洪堤夜间是否安全。')],M('His preoccupation with the restoration plan meant that he ignored the project completely and spent all his time on unrelated hobbies.','His preoccupation with the restoration plan meant that he gave it nearly all his attention.','preoccupation 表示注意力集中在某事上，与完全忽略它相反。','meaning'),[q('What occupied her attention?','the restoration project','a new collection of unrelated hobbies','the family’s flood barrier','修复项目占据了她的注意力。',1,'context'),q('What was the family worried about?','whether the barrier would hold overnight','whether a restoration project would sell','whether their hobbies were popular','家人挂念防洪堤能否撑过夜晚。',2,'context'),q('Which meaning of preoccupation fits a persistent concern?','a worry that keeps occupying the mind','a short public performance','a payment made to renew insurance','忧虑持续萦绕心头，符合 preoccupation 的担忧义。',2,'meaning'),q('Which historical idea is reflected in preoccupation?','taking possession beforehand','measuring an object twice','paying a prize afterward','词源 praeoccupatio 带有“先占有”的含义。',1,'word-formation')]);
P('preoccupy','Preoccupy combines pre- with occupy; it means to fill someone’s thoughts or to worry someone so much that attention is diverted from other matters.',[C('preoccupy.s1','使全神贯注；占据心思','The design problem continued to preoccupy the engineers throughout the weekend.','整个周末，这个设计难题一直占据着工程师们的心思。','The design problem continued to preoccupy the engineers / throughout the weekend.','preoccupy 可表示某事持续占据某人的注意力。','工程师整个周末都在想着设计难题。'),C('preoccupy.s2','使忧心忡忡','Concerns about the approaching storm preoccupied residents who had not yet secured their roofs.','即将到来的风暴令屋顶尚未加固的居民忧心忡忡。','Concerns about the approaching storm / preoccupied residents / with unsecured roofs.','preoccupy 也可表示使某人过度担心，以至于难以关注别的事。','居民担心风暴会损坏尚未加固的屋顶。')],M('The design problem preoccupied the engineers, so they never thought about it and focused only on weekend hobbies.','The design problem preoccupied the engineers, so they kept thinking about it throughout the weekend.','preoccupy 表示占据心思，与完全不去想该问题相反。','meaning'),[q('What occupied the engineers throughout the weekend?','the design problem','a neighborhood’s weekend market','the insurance renewal deadline','设计难题一直占据工程师的心思。'),q('Why were some residents preoccupied?','they feared the storm might damage unsecured roofs','they had already completed every repair','they were choosing a new design for engineers','居民担心风暴会影响未加固的屋顶。',2,'context'),q('Which sentence uses preoccupy to mean “fill someone’s thoughts”?','The puzzle preoccupied her all afternoon.','The puzzle occupied a shelf before the meeting.','She occupied the office after the meeting.','难题让她整个下午都在想着它，属于占据心思。',1,'meaning'),q('How is preoccupy formed?','pre- + occupy','pre- + prepare','pre- + occupy + -ness','preoccupy 由 pre- 与 occupy 构成。',1,'word-formation')]);
P('prep','Prep is an informal shortening of preparation or prepare; it means work done to get ready, often for a task, meal, or examination.',C('prep.s1','准备；预习；准备工作','The lab team finished the sample prep before the visiting researchers arrived.','实验室团队在来访研究人员抵达前完成了样品准备。','The lab team finished the sample prep / before the visiting researchers arrived.','prep 是 preparation 或 prepare 的非正式缩略形式，常指准备工作。','样品在研究人员到达前已准备好。'),M('The technician began sample prep after the analysis was complete and the samples had already been discarded.','The technician completed sample prep before the analysis began.','prep 是分析前的准备，不是样品丢弃后的工作。','context'),[q('What did the lab team finish before the visitors arrived?','preparing the samples','writing a report about the visitors','discarding the samples after analysis','实验室团队完成的是样品准备工作。'),q('What does prep mean here?','work done to get something ready','the final result of an experiment','a payment made before an insurance policy','prep 指为某项任务作准备。',1,'meaning'),q('Which phrase uses prep naturally?','exam prep for next week’s test','a prep that means the completed final report','to prep after the task is permanently over','exam prep 指考试前的准备。',1,'collocation'),q('Which full form is prep shortened from?','preparation or prepare','preponderance or premium','premier or premiere','prep 是 preparation 或 prepare 的缩略形式。',1,'word-formation')]);
P('preparation','Preparation comes from Old French preparacion and Latin praeparatio, from praeparare “make ready beforehand”; it names the act or process of getting ready.',C('preparation.s1','准备；预备','Careful preparation allowed the crew to evacuate the building quickly when the alarm sounded.','充分准备使工作人员在警报响起时能够迅速疏散大楼。','Careful preparation allowed the crew / to evacuate quickly / when the alarm sounded.','preparation 指为某事做好准备的过程或所做的准备。','预先制定计划和安排使疏散能够迅速进行。'),M('The crew evacuated quickly without preparation because nobody had planned routes, assigned roles, or reviewed the alarm.','The crew evacuated quickly after preparing routes, assigning roles, and reviewing the alarm plan.','例句强调提前准备帮助团队快速疏散；完全没有准备则不符合。','meaning'),[q('What helped the crew evacuate quickly?','careful preparation','a delayed warning after the alarm','an unplanned route chosen at random','预先准备帮助工作人员快速疏散。'),q('What does preparation name?','the process of getting ready','the act of leaving a building','the person who leads a government','preparation 指准备过程。',1,'meaning'),q('Which item is part of emergency preparation?','assigning evacuation roles before an alarm','deciding where to go only after the fire spreads','ignoring the exit plan','事先分配疏散职责属于应急准备。',1,'context'),q('What is the Latin verb behind preparation?','praeparare, “make ready beforehand”','praemium, “reward”','praeludere, “play beforehand”','preparation 来自表示预先备好的拉丁动词。',1,'word-formation')]);
P('preparatory','Preparatory comes from Late Latin praeparatorius, from praeparare “make ready beforehand”; it describes something done as preparation for a later action.',C('preparatory.s1','预备的；准备性的','Students took a preparatory course before beginning the advanced laboratory sequence.','学生在开始高级实验课程系列之前先修了一门预备课程。','Students took a preparatory course / before beginning / the advanced laboratory sequence.','preparatory 表示为之后的活动作准备的。','课程先行教授必要内容，帮助学生进入高级实验。'),M('The university called the course preparatory because it was taken after the advanced laboratory sequence had ended.','The university called the course preparatory because students took it before the advanced laboratory sequence.','准备性课程在后续高级课程之前修读，而不是结束之后。','context'),[q('When did students take the preparatory course?','before the advanced laboratory sequence','after the sequence had ended','only during the final examination','预备课程安排在高级实验课程之前。'),q('What does preparatory mean?','intended to prepare for something later','happening after all work is completed','describing a building’s grounds','preparatory 表示为后续活动作准备的。',1,'meaning'),q('Which is a preparatory step before a field study?','training students to use the equipment','publishing the final results','returning equipment after the study','出发前培训学生使用设备属于预备步骤。',1,'context'),q('Which word family supplies preparatory?','prepare / preparation','premier / premiere','prejudice / prejudicial','preparatory 属于 prepare 与 preparation 词族。',1,'word-formation')]);
P('prepare','Prepare came through Old French preparer from Latin praeparare, “make ready beforehand”; it means to get something ready, make oneself ready, or make food.',[C('prepare.s1','准备；使做好准备','Please prepare the display materials before the community meeting begins.','请在社区会议开始前准备好展示材料。','Please prepare the display materials / before the community meeting / begins.','prepare 可表示把物品、文件或安排准备妥当。','展示材料须在会议开始前备好。'),C('prepare.s2','为……作准备；使有准备','The orientation sessions prepare new volunteers for working safely with visitors.','入职说明会帮助新志愿者为安全接待访客做好准备。','The orientation sessions prepare new volunteers / for working safely / with visitors.','prepare someone for something 表示使某人为某事做好准备。','说明会训练志愿者安全接待访客。'),C('prepare.s3','烹调；调制','The cook prepared a simple soup from beans, tomatoes, and fresh herbs.','厨师用豆子、西红柿和新鲜香草煮了一道简单的汤。','The cook prepared a simple soup / from beans, tomatoes / and fresh herbs.','prepare 还可表示制作或烹调食物。','厨师把列出的食材做成汤。')],M('The cook prepared the soup by leaving all ingredients raw and never combining or heating them.','The cook prepared the soup by combining the beans, tomatoes, herbs, and broth and simmering them.','把食材烹调成汤需要组合并加热，而不是保持原样。','meaning'),[q('What should be ready before the community meeting?','the display materials','the final meeting minutes from next week','the cook’s raw ingredients only','会议开始前要准备好展示材料。',1,'context'),q('How do orientation sessions prepare volunteers?','they train them to work safely with visitors','they ask them to prepare soup','they replace every safety rule','说明会使志愿者为安全接待访客做好准备。',2,'context'),q('What did the cook prepare?','a soup made from beans, tomatoes, and herbs','a written premise for a meeting','a premium insurance policy','厨师准备了一道由豆子、西红柿和香草做成的汤。',3,'context'),q('Which use of prepare means “make oneself ready”?','She prepared for the interview by reviewing her notes.','She prepared the soup on the stove.','She prepared the display boards for the meeting.','为面试复习笔记体现为自己做好准备。',2,'meaning')]);
P('prepared','Prepared is the past participle and adjective from prepare; it means made ready or having planned and equipped oneself for an event.',C('prepared.s1','准备好的；有准备的','The prepared speaker tested the slides, checked the microphone, and arrived early.','准备充分的演讲者测试了幻灯片、检查了麦克风，并提前到场。','The prepared speaker tested the slides / checked the microphone / and arrived early.','prepared 可表示已做好准备，也可表示事先计划妥当。','演讲者提前检查设备并早到，体现准备充分。'),M('The speaker was prepared because she arrived without slides, had not tested the microphone, and had no plan.','The speaker was prepared because she checked the slides and microphone and arrived early.','没有材料、没有检查设备且没有计划说明未作准备。','meaning'),[q('What did the prepared speaker check?','the slides and microphone','the community’s flood barrier','the laboratory samples','演讲者检查了幻灯片和麦克风。'),q('What does prepared mean here?','ready for an event','not yet chosen for a role','happening too early','prepared 表示已为活动做好准备。',1,'meaning'),q('Which person is prepared for an interview?','one who has reviewed the role and organized needed documents','one who arrives without knowing the meeting time','one who has not read the invitation','预先了解职位并整理材料的人准备充分。',1,'context'),q('How is prepared related to prepare?','it is the past participle form used as an adjective','it is the plural noun for a building site','it is the comparative form of premier','prepared 是 prepare 的过去分词，也可作形容词。',1,'grammar')]);
P('preparedness','Preparedness is formed from prepared and -ness; it means the state of being ready to deal with a possible event, emergency, or threat.',C('preparedness.s1','准备状态；有备无患','The town improved its flood preparedness by rehearsing evacuation routes and storing clean water.','该镇通过演练疏散路线和储备饮用水来加强防洪准备。','The town improved its flood preparedness / by rehearsing routes / and storing clean water.','preparedness 指应对可能事件或紧急情况的准备状态。','演练路线并储水让居民更能应对洪水。'),M('The town’s flood preparedness improved when it removed all stored water and stopped practicing evacuation routes.','The town improved flood preparedness by storing water and rehearsing evacuation routes.','移除储水并停止演练会削弱而不是加强应急准备。','meaning'),[q('How did the town improve flood preparedness?','by practicing routes and storing clean water','by closing every evacuation route','by using the water supply for decoration','演练路线和储水增强了防洪准备。'),q('What does preparedness mean?','the state of being ready for a possible event','the act of announcing a winner too early','a public screening of a film','preparedness 指对可能事件有所准备的状态。',1,'meaning'),q('Which action shows earthquake preparedness?','keeping supplies and practicing a safe exit plan','waiting until shaking starts to locate every exit','blocking the building’s emergency doors','储备物资并演练安全出口体现地震准备。',1,'context'),q('Which suffix turns prepared into preparedness?','-ness','-er','-ment only','-ness 可把 prepared 转成表示状态的名词 preparedness。',1,'word-formation')]);
P('prepay','Prepay combines pre- “before” with pay; it means to pay for a service or item in advance.',C('prepay.s1','预付；预先付款','Travelers can prepay for checked baggage online and avoid the higher airport fee.','旅客可以在线预付托运行李费，避免支付较高的机场费用。','Travelers can prepay for checked baggage online / and avoid / the higher airport fee.','prepay 指在收到服务或商品之前先付款。','在线先行付款可以避免机场临时收费较高。'),M('Travelers prepaid for baggage only after the flight ended and the airport charged the fee.','Travelers prepaid for baggage online before arriving at the airport.','在航班结束并被收费之后付款不是预付。','meaning'),[q('How can travelers avoid the higher airport fee?','pay for checked baggage online in advance','wait until after the flight to buy baggage service','leave their bags at the airport','旅客可在线预先支付托运行李费。'),q('What does prepay mean?','pay before receiving a service or item','pay after the service has ended','pay an extra insurance premium each year','prepay 表示事先付款。',1,'meaning'),q('Which customer prepays?','one who pays for a ticket before traveling','one who settles the bill after using the service','one who refuses to pay any charge','出行前付款的顾客属于预付。',1,'context'),q('How is prepay formed?','pre- “before” + pay','pre- “before” + prepare','pre- “before” + prize','prepay 由表示“在前”的 pre- 与 pay 组成。',1,'word-formation')]);
P('preponderance','Preponderance comes from Latin praeponderare, “to outweigh,” formed from prae- and ponderare “weigh”; it means a greater amount, number, or influence on one side.',C('preponderance.s1','优势；较大数量；多数','A preponderance of the evidence supported the claim that the bridge needed urgent repairs.','大多数证据支持这座桥需要紧急维修的主张。','A preponderance of the evidence / supported the claim / that the bridge needed repairs.','preponderance 指某一方在数量、分量或影响上占优势。','支持维修主张的证据数量或分量更多。'),M('A preponderance of the evidence supported the opposite claim because nearly all reports rejected the need for repairs.','A preponderance of the evidence supported urgent repairs because most reports documented structural damage.','若几乎所有报告都反对维修，就不是支持维修的一方占多数。','meaning'),[q('What did most evidence support?','the need for urgent bridge repairs','the claim that the bridge was already new','the idea that reports should be discarded','大多数证据支持紧急维修桥梁的主张。'),q('What does preponderance mean?','a greater amount or number on one side','a payment made before a service','a condition of being ready','preponderance 表示一方在数量或分量上占优势。',1,'meaning'),q('Which report shows a preponderance of support?','eight of ten experts recommend the same repair','one expert recommends it and nine oppose it','all experts give unrelated recommendations','十位专家中有八位支持同一维修方案，构成多数。',1,'context'),q('Which Latin verb is behind preponderance?','praeponderare, “to outweigh”','praeparare, “to make ready”','praeludere, “to play before”','preponderance 来自表示“重于另一方”的拉丁动词。',1,'word-formation')]);
})();
